        const ICON = { heal: 'berry', magnet: 'magnet', bomb: 'bomb', stopwatch: 'stopwatch', ticket: 'ticket', ticket10: 'ticket10' };
        const sz = p.kind === 'ticket10' || p.kind === 'item' ? 24 : 18;
