/* js/ui/gacha-ui.js */
/* ============ gacha-ui.js — banners por generación y animación de tirada ============
 * La lógica (probabilidades, pity, shiny, repetidos) está en systems/gacha.js.
 */
G.GachaUI = (() => {
  const $ = G.UI.$;
  let busy = false;
  let gen = 1;
  let surprise = false;        // "Surprise me": each roll uses a random generation
  let demoSave = null;         // demo mode (code): pulls run on a throw-away copy of your save
  const demo = () => G.Redeem.demoMode();
  const sv = () => {
    if (!demo()) { demoSave = null; return G.DB.save; }
    if (!demoSave) demoSave = JSON.parse(JSON.stringify(G.DB.save));
    return demoSave;
  };
  let mystery = [];            // the three silhouettes on the mystery banner

  function init() {
    $('pull-1').onclick = () => pull(1);
    $('pull-10').onclick = () => pull(10, 't1');
    $('pull-10b').onclick = () => pull(10, 't10');
    $('pull-close').onclick = close;
    $('pull-all').onclick = pullAll;
    $('gacha-surprise').onclick = () => {
      surprise = !surprise;
      if (surprise) mystery = G.U.shuffle ? G.U.shuffle(G.DEX.filter(p => p.rarity === 5 && G.SPRITE_META[p.dex])).slice(0, 3).map(p => p.dex)
                                           : G.DEX.filter(p => p.rarity === 5 && G.SPRITE_META[p.dex]).sort(() => Math.random() - 0.5).slice(0, 3).map(p => p.dex);
      G.Audio.sfx('click');
      refresh();
    };

    const tabs = $('gacha-gens');
    G.Gacha.BANNERS.forEach(b => {
      const t = document.createElement('button');
      t.className = 'gen-tab';
      t.dataset.gen = b.gen;
      t.innerHTML = `<b>${b.name}</b><small>Gen ${b.gen}</small>`;
      t.onclick = () => { gen = b.gen; surprise = false; refresh(); };
      tabs.appendChild(t);
    });
  }

  function open() {
    demoSave = null;            // every visit starts a fresh demo copy
    G.UI.show('scr-gacha', true);
    refresh();
  }

  function refresh() {
    const s = G.DB.save;
    const banner = G.Gacha.BANNERS[gen - 1];
    document.querySelectorAll('#gacha-gens .gen-tab').forEach(t => t.classList.toggle('on', !surprise && +t.dataset.gen === gen));
    const sb = $('gacha-surprise');
    sb.classList.toggle('gold', surprise); sb.classList.toggle('ghost', !surprise);
    sb.setAttribute('aria-pressed', surprise ? 'true' : 'false');
    $('gacha-surprise-note').textContent = surprise ? 'ON: every roll comes from a random generation.' : 'Roll from a random generation instead of the one selected.';

    const all = surprise ? G.DEX.filter(p => G.SPRITE_META[p.dex]) : G.DEX.filter(p => p.gen === gen);
    const owned = all.filter(p => s.owned[p.dex]).length;
    const shinies = all.filter(p => s.shiny && s.shiny[p.dex]).length;
    const [c1, c2, c3] = surprise ? ['#2a0f55', '#12203f', '#4a1a6a'] : banner.color;
    $('banner').style.background =
      `radial-gradient(circle at 80% 30%, rgba(255,210,63,.3), transparent 45%),
       radial-gradient(circle at 15% 80%, rgba(196,123,255,.3), transparent 50%),
       linear-gradient(135deg, ${c1}, ${c2} 55%, ${c3})`;
    $('banner-title').textContent = surprise ? '??? Mystery Banner' : banner.name + ' Misterioso';
    $('banner-desc').textContent = surprise ? `Any of the ${all.length} Pokémon from any generation. Who knows what you will get?`
                                            : `Los ${all.length} Pokémon de la generación ${gen}. ¡Los legendarios esperan!`;
    $('gacha-owned').innerHTML = `Tienes ${owned} de ${all.length}` +
      (shinies ? ` · ${G.Icons.html('shiny', 12)} ${shinies} shiny` : '');

    const feat = $('gacha-feat');
    feat.innerHTML = '';
    if (surprise) {
      // Mystery style: dark silhouettes with a question mark instead of the featured Pokémon.
      for (const dex of mystery) {
        const w = document.createElement('div');
        w.className = 'mystery';
        w.appendChild(G.UI.spriteCanvas(dex, 170, 190, { silhouette: true, scale: 2, dir: 1 }));
        w.insertAdjacentHTML('beforeend', '<span>?</span>');
        feat.appendChild(w);
      }
    } else for (const dex of G.Gacha.featured(gen)) {
      feat.appendChild(G.UI.spriteCanvas(dex, 170, 190, { lively: true, scale: 2, dir: 1 }));
    }

    const ps = sv();
    const pity = (ps.pity && ps.pity[surprise ? 'x' : gen]) || 0;
    $('gacha-pity').textContent = `Tiradas sin legendaria en ${surprise ? 'Surprise' : banner.name}: ${pity} / ${G.Gacha.PITY_5}`;

    $('gacha-rates').innerHTML = '<h3>Probabilidades</h3>' + G.Gacha.RATES.slice().reverse().map(([r, w]) => `
      <div><span style="color:${G.Gacha.RARITY_COLOR[r]}">${G.UI.stars(r, 10)} ${G.Gacha.RARITY_NAME[r]}</span>
      <span>${w}% · ${surprise ? G.Gacha.BANNERS.reduce((n, b) => n + G.Gacha.pool(r, b.gen).length, 0) : G.Gacha.pool(r, gen).length}</span></div>`).join('') +
      `<div><span>${G.Icons.html('shiny', 12)} Shiny</span><span>1%</span></div>
       <p class="note">· La tirada ×10 garantiza al menos una Épica.<br>
       · A las ${G.Gacha.PITY_5} tiradas sin Legendaria en un banner, la siguiente lo es.<br>
       · Los repetidos dan Pokémonedas. Los shiny no se repiten.<br>
       · Los tickets se consiguen jugando: algunos Pokémon los sueltan al caer, y
         los jefes y los legendarios de las grietas, a veces, tickets ×10.</p>`;

    const t = s.tickets;
    $('cost-1').innerHTML = `${G.Icons.html('ticket', 18)} 1`;
    $('cost-10').innerHTML = `${G.Icons.html('ticket', 18)} 10`;
    $('cost-10b').innerHTML = `${G.Icons.html('ticket10', 18)} 1`;
    $('gacha-tickets').innerHTML = `Tienes ${G.Icons.html('ticket', 18)} <b>${t.t1}</b> tickets y ${G.Icons.html('ticket10', 18)} <b>${t.t10}</b> tickets ×10`;
    const dm = demo();
    $('pull-1').disabled = !dm && !G.Gacha.costOf(s, 1);
    $('pull-10').disabled = !dm && !G.Gacha.costOf(s, 10, 't1');
    $('pull-10b').disabled = !dm && !G.Gacha.costOf(s, 10, 't10');
    $('pull-all').disabled = !dm && !(t.t1 > 0 || t.t10 > 0);
    if (dm) $('gacha-pity').textContent += ' · DEMO MODE: pulls are free and nothing is saved';
    G.UI.refreshCoins();
  }

  const wait = ms => new Promise(r => setTimeout(r, ms));

  async function pull(n, use = 't1') {
    if (busy) return;
    let res;
    if (demo()) { const d = sv(); d.tickets = { t1: 1000, t10: 1000 }; res = G.Gacha.pull(d, n, gen, use, surprise); }
    else res = G.Gacha.pull(G.DB.save, n, gen, use, surprise);
    if (!res) { G.Audio.sfx('error'); G.UI.toast('No tienes tickets suficientes: consíguelos jugando'); return; }
    present(res, n);
  }

  /** Spend every ticket on the selected banner (or Surprise): ×10 tickets, then groups of 10, then singles. */
  async function pullAll() {
    if (busy) return;
    const real = G.DB.save.tickets;
    const s = sv();
    // Demo mode: simulate with your real ticket count (or a sample of 100 if you have none).
    if (demo()) s.tickets = (real.t1 || real.t10) ? { t1: real.t1, t10: real.t10 } : { t1: 100, t10: 0 };
    const t = s.tickets;
    const total = t.t1 + t.t10 * 10;
    if (!(t.t1 > 0 || t.t10 > 0)) { G.Audio.sfx('error'); G.UI.toast('You have no tickets'); return; }
    const where = surprise ? 'the Surprise banner' : G.Gacha.BANNERS[gen - 1].name;
    busy = true;                // no double clicks while the prompt is open
    const ok = await G.UI.ask('Use all tickets?',
      `Spend <b>${t.t1}</b> single and <b>${t.t10}</b> ×10 tickets (${total} pulls) on <b>${where}</b>?`, 'Use all', 'Cancel');
    busy = false;
    if (!ok) return;
    const res = [];
    const go = (n, use) => { const r = G.Gacha.pull(s, n, gen, use, surprise); if (r) res.push(...r); return !!r; };
    while (G.Gacha.costOf(s, 10, 't10') && go(10, 't10'));
    while (G.Gacha.costOf(s, 10, 't1') && go(10, 't1'));
    while (G.Gacha.costOf(s, 1) && go(1, 't1'));
    if (!res.length) return;
    present(res, res.length);
  }

  async function present(res, n) {
    if (!demo()) { G.Progress.checkAch(); G.DB.commit(true); }
    busy = true;

    const best = Math.max(...res.map(r => r.rarity));
    const many = res.length > 10;
    const fx = $('pull-fx'), slot = $('slot'), out = $('pull-results');
    out.innerHTML = '';
    if (demo()) out.insertAdjacentHTML('beforeend', '<div style="width:100%;text-align:center;color:#ffd23f"><b>DEMO MODE</b>: nothing was spent or saved</div>');
    $('pull-close').classList.add('hidden');
    slot.style.display = many ? 'none' : '';
    fx.classList.remove('hidden');

    // La tragaperras (ui/slots.js) y luego las cartas. (With "Use all tickets" there are too many: summary instead.)
    if (!many) await G.Slots.play(slot, res);
    G.Audio.sfx('burst', { rarity: best });
    slot.style.display = 'none';

    let list = res;
    if (many) {
      // Summary line, then only the notable results (new, shiny or Rare and above).
      const news = res.filter(r => r.isNew).length, shin = res.filter(r => r.shiny).length;
      const coins = res.reduce((a, r) => a + r.refund, 0);
      const top = Math.max(...res.map(r => r.rarity));
      out.insertAdjacentHTML('beforeend', `<div class="pull-sum" style="grid-column:1/-1;width:100%;text-align:center"><b>${res.length} pulls</b> · ${news} new${shin ? ' · ' + G.Icons.html('shiny', 12) + ' ' + shin + ' shiny' : ''} · <span class="coin"></span> +${coins} from duplicates · best: <span style="color:${G.Gacha.RARITY_COLOR[top]}">${G.Gacha.RARITY_NAME[top]}</span></div>`);
      list = res.filter(r => r.isNew || r.shiny || r.rarity >= 3);
    }
    // Slower reveal for "Use all tickets" (about 220 ms each, never more than ~10 s in total); click to skip ahead.
    const step = many ? Math.min(220, Math.max(60, 10000 / list.length)) : n === 10 ? 150 : 0;
    let fast = false;
    const speedUp = () => { fast = true; };
    fx.addEventListener('click', speedUp);
    for (const r of list) {
      const mon = G.DEX_BY[r.dex];
      const c = document.createElement('div');
      c.className = 'pcard r' + r.rarity + (r.shiny ? ' shiny' : '');
      c.style.setProperty('--rc', r.shiny ? '#9ae6ff' : G.Gacha.RARITY_COLOR[r.rarity]);
      c.innerHTML = `<div class="stars">${G.UI.stars(r.rarity, 24)}</div>`;
      c.appendChild(G.UI.spriteCanvas(r.dex, 132, 120, { lively: r.rarity >= 4 || r.shiny, scale: 2, shiny: r.shiny }));
      const tag = r.isNew
        ? `<span class="new">${r.shiny ? '¡SHINY NUEVO!' : '¡NUEVO!'}</span>`
        : `Repetido · <span class="coin"></span> +${r.refund}`;
      c.insertAdjacentHTML('beforeend', `<b>${r.shiny ? G.Icons.html('shiny', 12) + ' ' : ''}${mon.name}</b>${surprise ? `<small class="sub">Gen ${r.gen}</small>` : ''}<div class="tag">${tag}</div>`);
      out.appendChild(c);
      G.Audio.sfx('reveal', { rarity: r.rarity });
      await wait(fast ? 0 : step);
    }
    fx.removeEventListener('click', speedUp);
    $('pull-close').classList.remove('hidden');
    busy = false;
  }

  function close() {
    $('pull-fx').classList.add('hidden');
    refresh();
  }

  return { init, open, get open_() { return !$('pull-fx').classList.contains('hidden'); } };
})();

;
/* js/ui/run-ui.js */
/* ============ run-ui.js — cartas de nivel, pausa y fin de run ============ */
G.RunUI = (() => {
  const $ = G.UI.$;
  let offers = null, offerCb = null, coopMode = false;

  /** @param coop  en grupo: tras elegir, se queda esperando a los demás */
  function showLevelUp(level, list, cb, coop = false) {
    offerCb = cb; coopMode = coop;
    $('lvl-num').textContent = level;
    $('lvl-wait').textContent = '';
    $('lvl-wait').classList.toggle('hidden', !coop);
    $('cards').classList.remove('done');
    renderCards(list);
    $('lvl-reroll').onclick = reroll;
    $('lvl-skip').onclick = skip;
    G.UI.show('scr-levelup');
  }

  /**
   * Cambiar las cartas: 1 vez gratis por partida y 1 más por cada jefe
   * derrotado (en grupo cuentan los jefes del equipo; cada uno tiene los suyos).
   */
  function rerollsLeft() {
    const p = G.Game.player;
    // 1 gratis + los comprados en Mejoras (antes, 1 más por cada jefe).
    return p ? Math.max(0, 1 + (p.rerollBonus || 0) - (p.rerolls || 0)) : 0;
  }

  /** Skips bought in Upgrades (per run): take nothing from this level-up. */
  function skipsLeft() {
    const p = G.Game.player;
    return p ? Math.max(0, (p.skipBonus || 0) - (p.skips || 0)) : 0;
  }

  function skip() {
    if (!offers || skipsLeft() <= 0) return;
    const p = G.Game.player, cb = offerCb;
    p.skips = (p.skips || 0) + 1;
    offers = null; offerCb = null;
    $('lvl-reroll').classList.add('hidden');
    $('lvl-skip').classList.add('hidden');
    if (coopMode) $('cards').classList.add('done');
    else G.UI.hide('scr-levelup');
    G.UI.toast('Level-up skipped (' + skipsLeft() + ' left)');
    cb({ apply() {} });
  }

  function reroll() {
    if (!offers || rerollsLeft() <= 0) return;
    const p = G.Game.player;
    p.rerolls = (p.rerolls || 0) + 1;
    G.Audio.sfx('select');
    renderCards(G.LevelUp.offer(p));
  }

  function renderCards(list) {
    offers = list;
    const left = rerollsLeft();
    $('lvl-rr-n').textContent = left;
    $('lvl-reroll').classList.toggle('hidden', left <= 0);
    const sk = skipsLeft();
    $('lvl-skip-n').textContent = sk;
    $('lvl-skip').classList.toggle('hidden', sk <= 0);
    const box = $('cards');
    box.innerHTML = '';
    list.forEach((c, i) => {
      const el = document.createElement('div');
      el.className = 'card';
      const tag = c.type === 'new'
        ? `<span class="tag-chip" style="background:${c.color}">Nuevo · ${c.tag}</span>`
        : c.type === 'up' || c.type === 'evo'
          ? `<span class="tag-chip" style="background:${c.color}">${c.tag}</span>`
          : `<span class="tag-chip" style="background:${c.color === '#ffd23f' ? '#ffd23f' : '#9fb1c9'}">${c.tag}</span>`;
      if (c.type === 'evo') el.classList.add('evo');
      el.innerHTML =
        `<div class="ico" style="background:${c.color}33">${G.Icons.html(c.icon, 32)}</div>
         <div class="txt"><div class="nm">${c.title} ${tag}</div><div class="ds">${c.desc}</div></div>
         <div class="key">${i + 1}</div>`;
      el.dataset.sfx = 'none';             // el juego pone su propio sonido al elegir
      el.onclick = () => pick(i);
      box.appendChild(el);
    });
  }

  function pick(i) {
    if (!offers || !offers[i]) return;
    const c = offers[i], cb = offerCb;
    offers = null; offerCb = null;
    $('lvl-reroll').classList.add('hidden');
    $('lvl-skip').classList.add('hidden');
    if (coopMode) {
      // Se queda la carta elegida a la vista mientras eligen los demás.
      $('cards').querySelectorAll('.card').forEach((el, j) => el.classList.toggle('picked', j === i));
      $('cards').classList.add('done');
    } else G.UI.hide('scr-levelup');
    cb(c);
  }

  /** Cooperativo: quién falta por elegir. */
  function setWaiting(names) {
    const me = G.Social.me ? G.Social.me.name : '';
    const others = names.filter(n => n !== me);
    const list = a => a.length > 1 ? a.slice(0, -1).join(', ') + (G.I18n.lang === 'en' ? ' and ' : ' y ') + a[a.length - 1] : a[0];
    $('lvl-wait').textContent = !names.length ? ''
      : !others.length ? 'Elige tu carta'
      : names.includes(me) ? 'Faltan por elegir: ' + list([...others, G.I18n.lang === 'en' ? 'you' : 'tú'])
      : 'Esperando a ' + list(others) + '…';
  }

  function closeLevelUp() {
    offers = null; offerCb = null;
    $('cards').classList.remove('done');
    G.UI.hide('scr-levelup');
  }

  /**
   * Mensaje de apoyo (Ko-fi) al acabar: tras un récord o cada 10 partidas,
   * nunca en la primera y como mucho una vez al día. Se cierra con la X.
   */
  function askSupport(r) {
    if (!G.Funding || !G.Funding.url) return false;
    const runs = (G.DB.save && G.DB.save.stats && G.DB.save.stats.runs) || 0;
    if (runs < 2 || !(r.record || runs % 10 === 0)) return false;
    const today = new Date().toISOString().slice(0, 10);
    try { if (localStorage.getItem('ps.ask') === today) return false; localStorage.setItem('ps.ask', today); } catch (e) { return false; }
    return true;
  }

  // Stats tab: one column per player (everyone's numbers arrive from the other computers).
  let overRes = null;
  function refreshTeam() {
    const r = overRes, box = $('over-team');
    if (!r || !box) return;
    let list = r.team ? r.team() : [];
    if (!list.length) list = [r.mine];
    const rank = u => { const i = (r.order || []).indexOf(u); return i < 0 ? 99 : i; };
    list = list.slice().sort((a, b) => rank(a.u) - rank(b.u));
    const n = x => Math.round(x).toLocaleString('en-GB');
    const rows = [
      ['Damage dealt', p => p.d, n],
      ['Biggest hit', p => p.b, n],
      ['Damage taken', p => p.t, n],
      ['Times downed', p => p.dn, n],
      ['Revives given', p => list.reduce((s, q) => s + (q.rb || []).filter(u => u === p.u).length, 0), n],
      ['Shrines used', p => p.sr, n]
    ];
    const lowGood = new Set(['Damage taken', 'Times downed']);
    let h = '<table class="ptable"><thead><tr><th></th>' +
      list.map(p => `<th><span class="pc" data-dex="${p.dex}" data-sh="${p.sh ? 1 : 0}"></span><div translate="no">${esc(p.n)}</div></th>`).join('') + '</tr></thead><tbody>';
    for (const [label, get, fmt] of rows) {
      const vals = list.map(get), best = lowGood.has(label) ? Math.min(...vals) : Math.max(...vals);
      h += `<tr><td>${label}</td>` + vals.map(v => `<td class="${list.length > 1 && v === best && (v > 0 || lowGood.has(label)) ? 'top' : ''}">${fmt(v)}</td>`).join('') + '</tr>';
    }
    h += '</tbody></table>';
    if (list.length > 1) h += '<p class="sub" style="margin:8px 0 0">Gold marks the best in each row.</p>';
    box.innerHTML = h;
    box.querySelectorAll('.pc').forEach(el => {
      if (G.DEX_BY[+el.dataset.dex]) el.appendChild(G.UI.spriteCanvas(+el.dataset.dex, 44, 44, { shiny: el.dataset.sh === '1' }));
    });
  }
  const esc = s => String(s).replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));

  function showOver(r, onBack) {
    overRes = r;
    const setTab = t => {
      document.querySelectorAll('#over-tabs .tab').forEach(el => el.classList.toggle('on', el.dataset.tab === t));
      $('over-stats').classList.toggle('hidden', t !== 'sum');
      $('over-team').classList.toggle('hidden', t !== 'team');
      if (t === 'team') refreshTeam();
    };
    document.querySelectorAll('#over-tabs .tab').forEach(el => { el.onclick = () => setTab(el.dataset.tab); });
    setTab('sum');
    $('over-title').textContent = r.dead ? 'Has caído…' : 'Run terminada';
    $('over-stats').innerHTML = `
      <div><span>Tiempo</span><b>${G.U.mmss(r.time)}</b></div>
      <div><span>Nivel</span><b>${r.level}</b></div>
      <div><span>Derrotados</span><b>${r.kills}</b></div>
      <div><span>Jefes</span><b>${r.bosses}</b></div>
      ${r.judge ? `<div style="grid-column:1/-1"><span>Ante Arceus</span><b class="gold">${G.U.mmss(r.judge.time)} · ${r.judge.bosses} ${r.judge.bosses === 1 ? 'legendario' : 'legendarios'}</b></div>` : ''}
      <div style="grid-column:1/-1"><span>Pokémonedas ganadas</span>
        <b class="gold"><span class="coin"></span> +${r.coins}</b>
        <div style="font-size:12px;color:var(--muted)">${r.breakdown}</div></div>
      ${r.t1 || r.t10 ? `<div style="grid-column:1/-1"><span>Tickets del gacha</span><b>
        ${r.t1 ? G.Icons.html('ticket', 22) + ' +' + r.t1 + ' ' : ''}${r.t10 ? G.Icons.html('ticket10', 22) + ' +' + r.t10 + ' ×10' : ''}</b></div>` : ''}
      <div style="grid-column:1/-1"><span>Movimientos</span><b style="font-size:15px">
        ${r.moves.map(m => `${G.Icons.html('move:' + m.id, 16)} ${m.name} Nv.${m.lvl}`).join(' · ') || '—'}</b></div>
      ${r.caught && r.caught.length ? `<div style="grid-column:1/-1" class="caught"><span>${G.Icons.html('shiny', 12)} Shinies conseguidos</span>
        <div class="caught-row" id="over-caught"></div></div>` : ''}
      ${r.record ? '<div style="grid-column:1/-1;text-align:center" class="gold">¡Nuevo récord de tiempo!</div>' : ''}
      ${askSupport(r) ? `<div class="support-ask" id="over-ask" style="grid-column:1/-1">
        <button class="x" type="button" aria-label="Cerrar">×</button>
        <p>¿Te está gustando Megamon? Lo hago yo solo y los servidores cuestan dinero. Si quieres, puedes ayudarme a mantenerlo en línea.</p>
        <a class="btn small gold" href="${G.Funding.url}" target="_blank" rel="noopener">${G.Icons.html('heart', 14)} Apoyar en Ko-fi</a>
      </div>` : ''}`;
    const ask = $('over-ask');
    if (ask) ask.querySelector('.x').onclick = () => ask.remove();
    $('btn-again').onclick = onBack;
    if (r.caught && r.caught.length) {
      const row = $('over-caught');
      for (const c of r.caught) {
        const w = document.createElement('div');
        w.appendChild(G.UI.spriteCanvas(c.dex, 90, 72, { shiny: true, lively: true, scale: 2 }));
        w.insertAdjacentHTML('beforeend', `<small>${G.DEX_BY[c.dex].name}${c.isNew ? ' · ¡nuevo!' : ''}</small>`);
        row.appendChild(w);
      }
    }
    G.UI.show('scr-over');
  }

  /** Has encontrado un objeto llevando ya otro: ¿con cuál te quedas? */
  function showItemChoice(cur, next, cb) {
    const box = $('item-cards');
    box.innerHTML = '';
    // Sin objeto (cur = null): se ofrece el nuevo para aceptarlo o descartarlo.
    const opts = cur ? [[cur, 'Quedarme con'], [next, 'Cambiar a']] : [[next, 'Take'], [null, 'Discard']];
    opts.forEach(([id, verb], i) => {
      const it = id ? G.Items.BY[id] : null;
      const el = document.createElement('div');
      el.className = 'card' + (cur && i === 1 ? ' evo' : '');
      el.innerHTML = it
        ? `<div class="ico">${G.Icons.html(id, 36)}</div>
        <div class="txt"><div class="nm">${verb} ${it.name}</div><div class="ds">${it.desc}</div></div>
        <div class="key">${i + 1}</div>`
        : `<div class="ico">${G.Icons.html('ban', 36)}</div>
        <div class="txt"><div class="nm">${verb} ${G.Items.BY[next].name}</div><div class="ds">Leave it behind and keep going without an item.</div></div>
        <div class="key">${i + 1}</div>`;
      el.onclick = () => { G.UI.hide('scr-item'); cb(id); };
      box.appendChild(el);
    });
    $('item-title').textContent = 'An item!';
    $('item-sub').innerHTML = 'You can only carry one · <kbd>1</kbd> <kbd>2</kbd>';
    G.UI.show('scr-item');
  }

  /** Aegislash's Armoury: pick one of the offered items, or skip. */
  function showArmoury(cur, ids, cb) {
    const box = $('item-cards');
    box.innerHTML = '';
    ids.forEach((id, i) => {
      const it = G.Items.BY[id];
      const el = document.createElement('div');
      el.className = 'card';
      el.innerHTML = `<div class="ico">${G.Icons.html(id, 36)}</div>
        <div class="txt"><div class="nm">Take ${it.name}</div><div class="ds">${it.desc}</div></div>
        <div class="key">${i + 1}</div>`;
      el.onclick = () => { G.UI.hide('scr-item'); cb(id); };
      box.appendChild(el);
    });
    const skip = document.createElement('div');
    skip.className = 'card';
    skip.innerHTML = `<div class="ico">${G.Icons.html('ban', 36)}</div>
      <div class="txt"><div class="nm">Skip</div><div class="ds">${cur ? 'Take nothing and keep ' + G.Items.BY[cur].name + '.' : 'Take nothing and carry on without an item.'}</div></div>
      <div class="key">${ids.length + 1}</div>`;
    skip.onclick = () => { G.UI.hide('scr-item'); cb(null); };
    box.appendChild(skip);
    $('item-title').textContent = 'An Armoury of Items!';
    $('item-sub').innerHTML = (cur ? 'Taking one replaces ' + G.Items.BY[cur].name + ' · ' : 'You can only carry one · ') + 'keys <kbd>1</kbd>-<kbd>' + (ids.length + 1) + '</kbd>';
    G.UI.show('scr-item');
  }

  /** Choice Band just equipped: which move do you want to be locked into? */
  function showMoveChoice(pl, cb) {
    const box = $('item-cards');
    box.innerHTML = '';
    pl.slots.forEach((g, i) => {
      const m = g[0];
      if (!m) return;
      const nm = g.length > 1 ? m.name + ' +' + (g.length - 1) : m.name;
      const el = document.createElement('div');
      el.className = 'card' + (i === pl.active ? ' evo' : '');
      el.innerHTML = `<div class="ico">${G.Icons.html('move:' + m.id, 36)}</div>
        <div class="txt"><div class="nm">${nm}</div><div class="ds">${m.def.desc || ''}</div></div>
        <div class="key">${i + 1}</div>`;
      el.onclick = () => { G.UI.hide('scr-item'); cb(i); };
      box.appendChild(el);
    });
    $('item-title').textContent = 'Choice Band: pick your move';
    $('item-sub').innerHTML = 'You will be locked into it while you hold the band · <kbd>1</kbd>–<kbd>' + pl.slots.length + '</kbd>';
    G.UI.show('scr-item');
  }

  // ---------------- vínculo: qué movimientos se fusionan ----------------

  let bond = null;          // { opt, cb, first, list }

  /**
   * @param opt  pl.bondOptions(): 'add' (uno suelto al grupo) o 'pair' (dos sueltos, en dos pasos)
   * @param cb   recibe la lista de movimientos que se juntan
   */
  function showBond(opt, cb) {
    bond = { opt, cb, first: null, list: [] };
    $('bond-back').onclick = bondBack;
    renderBond();
    G.UI.show('scr-bond');
  }

  function renderBond() {
    const { opt, first } = bond;
    const names = ms => ms.map(m => m.name).join(' + ');
    const step2 = opt.mode === 'pair' && first;
    $('bond-sub').textContent = opt.mode === 'add' ? 'Elige qué movimiento se une a ' + names(opt.group)
      : step2 ? '¿Con cuál unes ' + first.name + '?' : 'Elige el primer movimiento que vas a unir';
    $('bond-back').classList.toggle('hidden', !step2);
    bond.list = step2 ? opt.loose.filter(m => m !== first) : opt.loose;
    const box = $('bond-cards');
    box.innerHTML = '';
    bond.list.forEach((m, i) => {
      const col = G.U.TYPE_COLOR[m.type];
      const desc = opt.mode === 'add' ? 'Se lanzará a la vez que ' + names(opt.group) + '.'
        : step2 ? 'Se lanzará a la vez que ' + first.name + '. Queda un hueco libre.'
        : m.desc || '';
      const el = document.createElement('div');
      el.className = 'card' + (opt.mode === 'add' || step2 ? ' bond' : '');
      el.innerHTML =
        `<div class="ico" style="background:${col}33">${G.Icons.html('move:' + m.id, 32)}</div>
         <div class="txt"><div class="nm">${m.name} <span class="tag-chip" style="background:${col}">Nv.${m.lvl}</span></div><div class="ds">${desc}</div></div>
         <div class="key">${i + 1}</div>`;
      el.dataset.sfx = 'none';
      el.onclick = () => pickBond(i);
      box.appendChild(el);
    });
  }

  function pickBond(i) {
    if (!bond || !bond.list[i]) return;
    const m = bond.list[i];
    if (bond.opt.mode === 'pair' && !bond.first) {
      bond.first = m;
      G.Audio.sfx('select');
      renderBond();
      return;
    }
    const picked = bond.opt.mode === 'add' ? [m] : [bond.first, m];
    const cb = bond.cb;
    bond = null;
    G.UI.hide('scr-bond');
    cb(picked);
  }

  function bondBack() {
    if (!bond) return;
    bond.first = null;
    renderBond();
  }

  function showPause(coop = false) {
    G.UI.soundControls($('pause-sound'));
    $('pause-coop').classList.toggle('hidden', !coop);
    $('btn-quit').textContent = coop ? 'Salir de la partida' : 'Abandonar run';
    G.UI.show('scr-pause');
  }

  function wirePause(onResume, onQuit) {
    $('btn-resume').onclick = onResume;
    $('btn-quit').onclick = onQuit;
  }

  return { showLevelUp, reroll, skip, showItemChoice, showArmoury, showMoveChoice, showBond, pickBond, bondBack, pick, setWaiting, closeLevelUp, showOver, refreshTeam, wirePause, showPause };
})();

;
/* js/ui/social-ui.js */
/* ============ social-ui.js — apodo, amigos, sala e invitaciones ============ */
(() => {
  const $ = G.UI.$;
  const esc = s => String(s).replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));

  /** ¿Se puede usar lo online? Si no, explica por qué. */
  function needOnline() {
    if (G.DB.online) return true;
    G.UI.toast(G.DB.guest ? 'Crea una cuenta para jugar con amigos y salir en el ranking.'
      : 'Esto necesita la versión online del juego (con la nube).', 3200);
    return false;
  }

  // ======================= APODO =======================

  G.NickUI = (() => {
    let then = null, skipped = false;

    function init() {
      $('nick-form').onsubmit = async e => {
        e.preventDefault();
        $('nick-err').textContent = '';
        $('nick-ok').disabled = true;
        const r = await G.Social.claimNick($('nick-in').value);
        $('nick-ok').disabled = false;
        if (!r.ok) { $('nick-err').textContent = r.error; G.Audio.sfx('error'); return; }
        G.Audio.sfx('confirm');
        G.UI.toast('Tu apodo es ' + G.Social.me.name);
        const cb = then; then = null;
        if (cb) cb(); else G.MenuUI.open();
      };
      $('nick-later').onclick = () => { skipped = true; then = null; G.MenuUI.open(); };
    }

    /** @param next  qué abrir después de elegirlo */
    function open(next) {
      then = next || null;
      G.UI.show('scr-nick');
      $('nick-err').textContent = '';
      $('nick-in').value = '';
      setTimeout(() => $('nick-in').focus(), 50);
    }

    return { init, open, get skipped() { return skipped; } };
  })();

  /** Abre `fn` si tienes apodo; si no, pide el apodo primero. */
  function withNick(fn) {
    if (!needOnline()) return;
    if (G.Social.me) { fn(); return; }
    G.Social.start().then(r => { if (r === 'ok') fn(); else G.NickUI.open(fn); });
  }

  // ======================= AMIGOS =======================

  G.FriendsUI = (() => {
    function init() {
      $('fr-add').onsubmit = async e => {
        e.preventDefault();
        const name = $('fr-name').value;
        msg('');
        const r = await G.Social.request(name);
        msg(r.ok ? r.msg : r.error, !r.ok);
        if (r.ok) $('fr-name').value = '';
      };
      $('fr-room').onclick = () => G.LobbyUI.open();
      G.Social.on(() => { if (G.UI.isOpen('scr-friends')) render(); });
    }

    function msg(t, bad) {
      $('fr-msg').textContent = t || '';
      $('fr-msg').style.color = bad ? '#ffb0b8' : '';
      if (t) G.Audio.sfx(bad ? 'error' : 'confirm');
    }

    function open() { withNick(() => { G.UI.show('scr-friends', true); msg(''); render(); G.Social.refreshPresence(); }); }

    /** "hace 5 min", "hace 2 h", "hace 3 días". */
    function ago(t) {
      const m = Math.max(1, Math.round((G.Social.now() - t) / 60000));
      if (m < 60) return 'hace ' + m + ' min';
      const h = Math.round(m / 60);
      if (h < 48) return 'hace ' + h + ' h';
      return 'hace ' + Math.round(h / 24) + ' días';
    }

    function stateText(f) {
      if (f.status === 'in') return 'Quiere ser tu amigo';
      if (f.status === 'out') return 'Solicitud enviada';
      if (!f.online) return f.seen ? 'Visto ' + ago(f.seen) : 'Desconectado';
      return f.play ? 'Jugando' : 'En línea';
    }

    function render() {
      const room = G.Social.room;
      $('fr-me').innerHTML = 'Tu apodo: <b class="gold" translate="no">' + esc(G.Social.me ? G.Social.me.name : '') + '</b> · dáselo a tus amigos para que te añadan.';
      $('fr-room').classList.toggle('hidden', !room);
      const list = G.Social.friends.sort((a, b) => {
        const rank = f => f.status === 'in' ? 0 : f.status === 'ok' ? (f.online ? (f.play ? 2 : 1) : 3) : 4;
        return rank(a) - rank(b) || a.name.localeCompare(b.name);
      });
      const box = $('fr-list');
      box.innerHTML = '';
      if (!list.length) {
        box.innerHTML = '<p class="sub">Aún no tienes amigos añadidos. Escribe arriba el apodo de un amigo.</p>';
        return;
      }
      for (const f of list) {
        const el = document.createElement('div');
        el.className = 'fr-row';
        const dot = f.status !== 'ok' ? 'pend' : !f.online ? 'off' : f.play ? 'play' : 'on';
        const inRoom = room && room.members.some(m => m.uid === f.uid);
        el.innerHTML = `<i class="dot ${dot}"></i><b translate="no"><a href="#" class="plink" title="Ver su perfil">${esc(f.name)}</a></b><span class="st">${inRoom ? 'En tu sala' : stateText(f)}</span><span class="grow"></span>`;
        if (f.status === 'ok') el.querySelector('.plink').onclick = e => { e.preventDefault(); G.ProfileUI.show(f.uid); };
        if (f.status === 'ok') {
          // Favourite Pokémon (up to 3) next to the name; profile comes from the 10-min cache.
          const favs = document.createElement('span');
          favs.className = 'fr-favs';
          el.querySelector('.st').before(favs);
          Promise.resolve(G.Social.getProfile(f.uid)).then(pr => {
            if (!pr || !favs.isConnected) return;
            for (const fv of (pr.favs || []).slice(0, 3)) {
              const d = G.DEX_BY[fv.dex];
              if (!d) continue;
              const cv = G.UI.spriteCanvas(fv.dex, 36, 36, { shiny: !!fv.shiny });
              cv.title = (fv.shiny ? 'Shiny ' : '') + d.name;
              favs.appendChild(cv);
            }
          }).catch(() => {});
        }
        else el.querySelector('.plink').onclick = e => e.preventDefault();
        const btn = (txt, cls, fn) => {
          const b = document.createElement('button');
          b.className = 'btn small ' + cls; b.textContent = txt; b.onclick = fn; el.appendChild(b); return b;
        };
        if (f.status === 'in') {
          btn('Aceptar', 'gold', async () => { const r = await G.Social.accept(f.uid); msg(r.ok ? r.msg : r.error, !r.ok); });
          btn('Rechazar', 'ghost', () => G.Social.remove(f.uid));
        } else if (f.status === 'out') {
          btn('Cancelar', 'ghost', () => G.Social.remove(f.uid));
        } else {
          const n = G.Chat.unread(f.uid);
          const cb = btn(n ? 'Chat (' + n + ')' : 'Chat', n ? 'gold' : 'ghost', () => G.DMUI.open(f.uid));
          cb.title = n ? n + ' unread' : 'Chat with ' + f.name;
          if (f.online && !f.play && !inRoom && (!room || room.isHost)) {
            btn('Invitar', 'gold', async () => {
              const r = await G.Social.invite(f.uid);
              msg(r.ok ? r.msg : r.error, !r.ok);
              if (r.ok) G.LobbyUI.open();
            });
          }
          // Quitar amigo: hay que pulsar dos veces (la primera pide confirmar y se desarma sola),
          // y va separado de "Invitar" para no darle sin querer.
          let armed = false, armT = 0;
          const rm = btn('Remove', 'ghost', () => {
            if (armed) { clearTimeout(armT); G.Social.remove(f.uid); return; }
            armed = true;
            rm.textContent = 'Sure? Tap again';
            rm.style.color = '#ff8a96'; rm.style.borderColor = '#ff8a96';
            armT = setTimeout(() => { armed = false; rm.textContent = 'Remove'; rm.style.color = ''; rm.style.borderColor = ''; }, 3500);
          });
          rm.style.marginLeft = '18px';
        }
        box.appendChild(el);
      }
    }

    return { init, open, render };
  })();

  // ======================= SALA =======================

  G.LobbyUI = (() => {
    let membersKey = '';

    function init() {
      $('lobby-leave').onclick = async () => {
        await G.Social.leaveRoom();
        G.Net.close();
        G.MenuUI.open();
      };
      $('lobby-menu').onclick = () => G.MenuUI.open();
      const diag = () => {
        const room = G.Social.room, names = {};
        if (room) for (const m of room.members) names[m.uid] = m.name;
        $('lobby-diag-text').value = G.Net.report(names);
      };
      $('lobby-diag').addEventListener('toggle', () => { if ($('lobby-diag').open) diag(); });
      $('lobby-diag-copy').onclick = async () => {
        diag();
        const t = $('lobby-diag-text');
        try { await navigator.clipboard.writeText(t.value); G.UI.toast('Copied', 1400); }
        catch (e) { t.select(); G.UI.toast('Select and copy the text', 2200); }
      };
      $('lobby-start').onclick = start;
      $('lobby-start').dataset.sfx = 'confirm';
      // Conecta / desconecta la red al entrar o salir de una sala.
      G.Social.on(what => {
        const room = G.Social.room;
        if (room) {
          G.Net.open(room.id, room.isHost, room.host);
          G.Net.syncMembers(room.members.map(m => m.uid));
        } else if (G.Net.open_) G.Net.close();
        if (what === 'room-closed') {
          G.UI.toast('La sala se ha cerrado', 2600);
          if (G.UI.isOpen('scr-lobby')) G.MenuUI.open();
        }
        if (G.UI.isOpen('scr-lobby')) render();
      });
      G.Net.onPeer(() => { if (G.UI.isOpen('scr-lobby')) render(); });
    }

    function open() {
      if (!G.Social.room) { G.MenuUI.open(); return; }
      G.Social.refreshMember();
      G.Social.refreshPresence();
      G.UI.show('scr-lobby', true);
      membersKey = '';
      render();
    }

    function close() { G.UI.hide('scr-lobby'); }

    /** What a guest sees about the link to the host: { cls: 'wait' | 'ok' | 'bad', text, hint, short }. */
    function guestLink(room) {
      const host = (room.members.find(m => m.uid === room.host) || {}).name || 'the host';
      switch (G.Net.mode(room.host)) {
        case 'direct': return { cls: 'ok', text: 'Connected to ' + host, hint: 'Waiting for ' + host + ' to start the game.', short: 'Host · Connected' };
        case 'relay': return { cls: 'ok', text: 'Connected to ' + host + ' (through the server)', hint: 'Your network blocks a direct link, so the game goes through the server. Waiting for ' + host + ' to start.', short: 'Host · Connected (server)' };
        case 'failed': return { cls: 'bad', text: "Couldn't connect to " + host, hint: 'Retrying automatically. If it keeps failing, check your internet connection.', short: 'Host · Not connected' };
        default: return { cls: 'wait', text: 'Connecting to ' + host + '…', hint: 'Setting up the link. This can take up to 15 seconds.', short: 'Host · Connecting…' };
      }
    }

    function connText(m, room) {
      if (m.uid === room.host) return room.isHost ? 'Anfitrión' : guestLink(room).short;
      if (!room.isHost) return m.uid === G.Social.uid ? 'Tú' : 'En la sala';
      const mode = G.Net.mode(m.uid);
      return mode === 'direct' ? 'Conectado' : mode === 'relay' ? 'Conectado (por servidor)' : mode === 'failed' ? 'No se pudo conectar (reintentando…)' : 'Conectando…';
    }

    function render() {
      const room = G.Social.room;
      if (!room) return;
      if (G.RoomChatUI) G.RoomChatUI.renderLobby();
      const ms = room.members;
      $('lobby-sub').textContent = room.isHost
        ? 'Eres el anfitrión. Invita a tus amigos (hasta ' + G.Social.MAX_PLAYERS + ') y empezad cuando estéis.'
        : 'Estás en la sala de ' + ((ms.find(m => m.uid === room.host) || {}).name || '…') + '. El anfitrión empezará la partida.';

      // Las tarjetas sólo se rehacen si cambian los miembros (los sprites no parpadean).
      const key = ms.map(m => m.uid + ':' + m.dex + ':' + (m.shiny ? 1 : 0)).join('|');
      const box = $('lobby-members');
      if (key !== membersKey) {
        membersKey = key;
        box.innerHTML = '';
        for (let i = 0; i < G.Social.MAX_PLAYERS; i++) {
          const m = ms[i];
          const c = document.createElement('div');
          c.className = 'lob-card' + (m ? '' : ' empty');
          if (m) {
            c.style.setProperty('--pc', G.Coop.COLORS[i]);
            c.appendChild(G.UI.spriteCanvas(m.dex, 120, 96, { scale: 2, lively: true, shiny: !!m.shiny }));
            c.insertAdjacentHTML('beforeend', `<b translate="no">${esc(m.name)}</b><small>${esc((G.DEX_BY[m.dex] || {}).name || '')}</small><span class="conn" data-u="${m.uid}"></span>`);
          } else c.innerHTML = '<span>Libre</span>';
          box.appendChild(c);
        }
      }
      box.querySelectorAll('.conn').forEach(el => {
        const m = ms.find(x => x.uid === el.dataset.u);
        if (!m) return;
        const t = connText(m, room);
        el.textContent = t;
        const gl = !room.isHost && m.uid === room.host ? guestLink(room) : null;
        el.className = 'conn' + (gl ? (gl.cls === 'ok' ? '' : ' ' + gl.cls) : t === 'Conectando…' ? ' wait' : '');
      });

      // Invitar (sólo el anfitrión y si queda sitio).
      const canInvite = room.isHost && ms.length < G.Social.MAX_PLAYERS;
      $('lobby-inv-title').classList.toggle('hidden', !canInvite);
      const inv = $('lobby-invite');
      inv.classList.toggle('hidden', !canInvite);
      if (canInvite) {
        inv.innerHTML = '';
        const free = G.Social.friends.filter(f => f.status === 'ok' && f.online && !ms.some(m => m.uid === f.uid));
        if (!free.length) inv.innerHTML = '<p class="sub" style="margin:0">Ningún amigo en línea ahora mismo.</p>';
        for (const f of free) {
          const el = document.createElement('div');
          el.className = 'fr-row';
          el.innerHTML = `<i class="dot ${f.play ? 'play' : 'on'}"></i><b translate="no">${esc(f.name)}</b><span class="st">${f.play ? 'Jugando' : 'En línea'}</span><span class="grow"></span>`;
          const b = document.createElement('button');
          b.className = 'btn small gold'; b.textContent = 'Invitar';
          b.onclick = async () => { const r = await G.Social.invite(f.uid); G.UI.toast(r.ok ? r.msg : r.error); };
          el.appendChild(b);
          inv.appendChild(el);
        }
      }

      // Guests: a clear status line about the link to the host.
      const st = $('lobby-status');
      st.classList.toggle('hidden', room.isHost);
      if (!room.isHost) {
        const gl = guestLink(room);
        st.className = 'lobby-status ' + gl.cls;
        $('lobby-status-text').textContent = gl.text;
        $('lobby-status-hint').textContent = gl.hint;
      }
      const btn = $('lobby-start');
      btn.classList.toggle('hidden', !room.isHost);
      const connecting = ms.some(m => m.uid !== room.host && G.Net.mode(m.uid) === 'connecting');
      const failed = ms.some(m => m.uid !== room.host && G.Net.mode(m.uid) === 'failed');
      btn.disabled = !room.isHost || ms.length < 2 || connecting || failed;
      btn.textContent = 'Empezar partida (' + ms.length + '/' + G.Social.MAX_PLAYERS + ')';
      $('lobby-note').textContent = !room.isHost ? ''
        : ms.length < 2 ? 'Necesitas al menos un amigo en la sala.'
        : failed ? 'No se puede conectar con algún amigo: su red (o la tuya) no deja jugar en grupo. Probad con otra wifi o datos móviles; se reintenta solo.'
        : connecting ? 'Conectando con tus amigos…' : 'La partida empieza para todos a la vez.';
    }

    function start() {
      const room = G.Social.room;
      if (!room || !room.isHost || room.members.length < 2) return;
      const cfg = {
        k: 'start', seed: Math.floor(Math.random() * 1e6), host: room.host,
        // Tu propio compañero se toma de tu partida guardada (lo más reciente), no de lo que
        // ya haya llegado de vuelta de la sala.
        members: room.members.map(m => m.uid === G.Social.uid
          ? { uid: m.uid, name: m.name, dex: G.DB.save.partner, shiny: !!G.DB.save.partnerShiny && G.DB.ownsShiny(G.DB.save.partner) }
          : { uid: m.uid, name: m.name, dex: m.dex, shiny: !!m.shiny })
      };
      G.Social.setOpen(false);
      G.Net.broadcast(cfg);
      G.Flow.startCoop(cfg);
    }

    return { init, open, close, render };
  })();

  // ======================= INVITACIONES =======================

  G.InvitePop = (() => {
    let cur = null;

    function init() {
      $('inv-yes').onclick = async () => {
        if (!cur) return;
        const from = cur.from, who = cur.name;
        // En plena partida: se pregunta si quieres dejarla; si sí, se cierra (se guarda
        // lo ganado, como al abandonar) y sólo entonces te unes a la sala.
        const st = G.Game.state;
        if (st !== 'ui') {
          if (st !== 'over' && !confirm('You are in the middle of a run. Leave it to join ' + who + "'s room? What you have earned so far will be saved.")) return;
          hide();
          G.Game.quit();
          G.UI.hideAll();
          G.Game.toUI();
          G.Audio.music('village');
        } else hide();
        G.UI.toast('Joining ' + who + "'s room…", 2500);
        const r = await G.Social.acceptInvite(from);
        if (!r.ok) { G.UI.toast(r.error, 3000); if (G.Game.state === 'ui') G.Flow.goMenu(); return; }
        G.LobbyUI.open();
      };
      $('inv-no').onclick = () => { if (cur) G.Social.declineInvite(cur.from); hide(); };
      G.Social.on(what => { if (what === 'invites' || what === 'room') refresh(); });
    }

    function hide() { cur = null; $('invite-pop').classList.add('hidden'); }

    /** Enseña la invitación más antigua (también en plena partida: al aceptar se pregunta si dejas la run). */
    function refresh() {
      const room = G.Social.room;
      const list = G.Social.invites.filter(i => !room || i.room !== room.id).sort((a, b) => a.at - b.at);
      if (!list.length || !G.DB.loggedIn) { hide(); return; }
      if (cur && cur.from === list[0].from) return;
      cur = list[0];
      $('inv-text').innerHTML = `${G.Icons.html('friends', 22)} <b class="gold" translate="no">${esc(cur.name)}</b> te invita a jugar en su sala`;
      $('invite-pop').classList.remove('hidden');
      G.Audio.sfx('shiny');
    }

    return { init, refresh };
  })();

  G.SocialUI = {
    init() { G.NickUI.init(); G.FriendsUI.init(); G.LobbyUI.init(); G.InvitePop.init(); },
    withNick, needOnline
  };
})();

;
/* js/ui/chat-ui.js */
/* ============ chat-ui.js — pantallas del chat ============
 *   G.DMUI      chat privado con un amigo (desde Amigos → Chat)
 *   G.RoomChatUI  chat de sala: en la sala de espera y, durante la partida, un cuadro
 *                 pequeño abajo a la izquierda (Intro para escribir, Esc para cerrar)
 * Los textos de otros jugadores se ponen siempre con textContent (nunca como HTML).
 */
(() => {
  const $ = id => document.getElementById(id);

  const clock = at => { try { return new Date(at).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }); } catch (e) { return ''; } };

  /** Dibuja líneas { mine, name, t, at } en un contenedor y baja al final si ya estabas abajo. */
  function renderLines(box, lines, opts = {}) {
    const atEnd = box.scrollHeight - box.scrollTop - box.clientHeight < 40;
    box.textContent = '';
    if (!lines.length && opts.empty) {
      const p = document.createElement('div');
      p.className = 'cm-empty'; p.textContent = opts.empty;
      box.appendChild(p);
    }
    for (const l of lines) {
      const row = document.createElement('div');
      row.className = 'cm ' + (l.mine ? 'me' : 'them');
      const who = document.createElement('b');
      who.textContent = l.name;
      if (l.c) who.style.color = l.c;
      const txt = document.createElement('span');
      txt.className = 'cm-t';
      txt.textContent = l.t;
      row.append(who, txt);
      if (opts.time && l.at) { const t = document.createElement('i'); t.textContent = clock(l.at); row.appendChild(t); }
      box.appendChild(row);
    }
    if (atEnd || opts.stick) box.scrollTop = box.scrollHeight;
  }

  // ======================= CHAT PRIVADO =======================

  G.DMUI = (() => {
    let other = null;

    const friend = () => G.Social.friends.find(f => f.uid === other && f.status === 'ok');

    function init() {
      $('chat-back').onclick = () => { other = null; G.FriendsUI.open(); };
      $('chat-mute').onclick = () => {
        if (!other) return;
        G.Chat.setMuted(other, !G.Chat.isMuted(other));
        G.Audio.sfx('select');
      };
      $('chat-form').onsubmit = async e => {
        e.preventDefault();
        if (!other) return;
        const inp = $('chat-input'), text = inp.value;
        if (!G.Chat.clean(text)) return;
        const r = await G.Chat.send(other, text);
        note(r.ok ? '' : r.error);
        if (r.ok) { inp.value = ''; G.Audio.sfx('select'); }
        inp.focus();
      };
      G.Chat.on((what, a, b) => {
        if (what === 'dm-new') {
          const f = G.Social.friends.find(x => x.uid === a);
          const here = G.UI.isOpen('scr-chat') && other === a;
          if (f && !here && !G.Chat.isMuted(a) && G.Game.state === 'ui') {
            G.UI.toast(f.name + ': ' + b.t.slice(0, 60), 3200);
            G.Audio.sfx('select');
          }
        }
        if (G.UI.isOpen('scr-chat') && other && (what === 'dm' || what === 'mute') && (a === other || !a)) {
          render();
          G.Chat.markRead(other);
        }
        if (G.UI.isOpen('scr-friends')) G.FriendsUI.render();
        G.MenuUI.refreshSocial && G.MenuUI.refreshSocial();
      });
      // Si el amigo desaparece de la lista (lo quitó), se vuelve a Amigos.
      G.Social.on(() => { if (G.UI.isOpen('scr-chat') && other && !friend()) { other = null; G.FriendsUI.open(); } });
    }

    function note(t) { $('chat-note').textContent = t || ''; if (t) G.Audio.sfx('error'); }

    function open(uid) {
      const f = G.Social.friends.find(x => x.uid === uid && x.status === 'ok');
      if (!f) return;
      other = uid;
      G.UI.show('scr-chat', true);
      note('');
      render(true);
      G.Chat.markRead(uid);
      setTimeout(() => { const i = $('chat-input'); if (i) i.focus(); }, 60);
    }

    function render(stick) {
      const f = friend();
      if (!f) return;
      const muted = G.Chat.isMuted(other);
      $('chat-title').textContent = 'Chat with ' + f.name;
      $('chat-mute').textContent = muted ? 'Unmute' : 'Mute';
      $('chat-sub').textContent = muted
        ? 'You muted ' + f.name + ': their messages are hidden and will not notify you.'
        : 'Your last ' + G.Chat.DM_KEEP + ' messages together are kept.';
      const me = G.Social.me ? G.Social.me.name : 'You';
      const lines = G.Chat.history(other)
        .filter(m => !(muted && m.f === other))
        .map(m => ({ mine: m.f !== other, name: m.f === other ? f.name : me, t: String(m.t || ''), at: m.at, c: G.Cosmetics.validColor(m.c) }));
      renderLines($('chat-log'), lines, { time: true, stick, empty: 'No messages yet. Say hi!' });
    }

    return { init, open, render };
  })();

  // ======================= CHAT DE SALA =======================

  G.RoomChatUI = (() => {
    const SHOW_MS = 10000;                 // en la partida, cada línea se ve 10 s
    let runKey = '';

    const inRun = () => G.Coop.active && G.Game.state !== 'ui';
    const lines = () => G.Chat.roomLog().map(l => ({ mine: l.u === G.Social.uid, name: l.name, t: l.t, at: l.at, c: l.c }));

    function init() {
      // Sala de espera.
      $('lobby-chatform').onsubmit = e => {
        e.preventDefault();
        const inp = $('lobby-chatinput');
        const r = G.Chat.sendRoom(inp.value);
        if (r.ok) { inp.value = ''; G.Audio.sfx('select'); } else if (r.error) G.UI.toast(r.error, 1600);
        inp.focus();
      };
      // Durante la partida.
      const form = $('chat-run-form'), inp = $('chat-run-input');
      form.onsubmit = e => {
        e.preventDefault();
        if (G.Chat.clean(inp.value)) {
          const r = G.Chat.sendRoom(inp.value);
          if (!r.ok) { if (r.error) G.UI.toast(r.error, 1600); return; }
        }
        inp.value = '';
        closeInput();
      };
      inp.onkeydown = e => {
        e.stopPropagation();
        if (e.key === 'Escape') { e.preventDefault(); inp.value = ''; closeInput(); }
      };
      inp.onblur = () => setTimeout(() => { if (document.activeElement !== inp) closeInput(); }, 50);
      $('chat-run-btn').onclick = () => openInput();
      addEventListener('keydown', e => {
        if (e.key !== 'Enter' || e.repeat) return;
        const t = e.target;
        if (t && (t.tagName === 'INPUT' || t.tagName === 'TEXTAREA')) return;
        const st = G.Game.state;
        if (!inRun() || (st !== 'playing' && st !== 'held')) return;
        e.preventDefault();
        openInput();
      });
      G.Chat.on(what => {
        if (what !== 'room' && what !== 'mute') return;
        if (G.UI.isOpen('scr-lobby')) renderLobby(true);
        renderRun();
      });
      G.Social.on(what => { if (what === 'room' && G.UI.isOpen('scr-lobby')) renderLobby(); });
      setInterval(tick, 500);
    }

    function renderLobby(stick) {
      renderLines($('lobby-chatlog'), lines(), { stick, empty: 'Nobody has said anything yet.' });
    }

    function openInput() {
      if (!inRun()) return;
      $('chat-run-form').classList.remove('hidden');
      $('chat-run-input').focus();
      renderRun();
    }
    function closeInput() {
      const f = $('chat-run-form');
      if (f.classList.contains('hidden')) return;
      f.classList.add('hidden');
      $('chat-run-input').blur();
      renderRun();
    }

    /** Las últimas líneas, y sólo las recientes (todas mientras escribes). */
    function renderRun() {
      const typing = !$('chat-run-form').classList.contains('hidden');
      const t = Date.now();
      const recent = G.Chat.roomLog().filter(l => typing || t - l.at < SHOW_MS).slice(-6);
      const key = recent.map(l => l.at + l.t).join('|');
      if (key === runKey) return;            // nothing new: don't rebuild
      runKey = key;
      renderLines($('chat-run-log'), recent.map(l => ({ mine: l.u === G.Social.uid, name: l.name, t: l.t, c: l.c })), { stick: true });
    }

    function tick() {
      const on = inRun();
      $('chat-run').classList.toggle('hidden', !on);
      if (!on) { if (!$('chat-run-form').classList.contains('hidden')) closeInput(); return; }
      renderRun();
    }

    return { init, renderLobby };
  })();

  // Se engancha a la inicialización de la parte social.
  const baseInit = G.SocialUI.init;
  G.SocialUI.init = () => { baseInit(); G.DMUI.init(); G.RoomChatUI.init(); };
})();

;
/* js/ui/ranking-ui.js */
/* ============ ranking-ui.js — pantalla del ranking ============
 * Pestañas Solo / Grupo, periodo (diario ... histórico), todos o sólo amigos,
 * filtro por Pokémon (sólo en el histórico) y tu puesto abajo aunque no salgas
 * en el top. Lo leído se guarda 30 min (ver ranking.js).
 */
G.RankingUI = (() => {
  const $ = G.UI.$;
  const esc = s => String(s).replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
  let mode = 's', period = 'w', scope = 'all', dex = null, metric = 't';      // metric: 't' time survived · 'k' most kills
  const eff = () => mode + (metric === 'k' ? 'k' : '');
  let token = 0;

  function init() {
    const dl = $('rk-dl');
    dl.innerHTML = G.DEX.map(p => `<option value="${esc(p.name)}">`).join('');
    $('rk-poke').onchange = () => {
      const v = $('rk-poke').value.trim().toLowerCase();
      const p = G.DEX.find(x => x.name.toLowerCase() === v);
      if (!v) { setDex(null); return; }
      if (!p) { G.UI.toast('No hay ningún Pokémon con ese nombre'); return; }
      setDex(p.dex);
    };
    $('rk-clear').onclick = () => { $('rk-poke').value = ''; setDex(null); };
    $('rk-mod').onclick = () => G.ModUI.open();
  }

  /** El filtro por Pokémon sólo existe en el histórico: al elegir uno se pasa a esa pestaña. */
  function setDex(d) {
    dex = d;
    if (d) { metric = 't'; if (period !== 'a') period = 'a'; }
    $('rk-clear').classList.toggle('hidden', !d);
    tabs(); load();
  }

  function open() {
    if (!G.SocialUI.needOnline()) return;
    G.UI.show('scr-rank', true);
    if (!G.Social.started) G.Social.start();
    $('rk-mod').classList.toggle('hidden', !G.Ranking.isAdmin());
    tabs();
    load();
  }

  function tabs() {
    const mk = (box, items, cur, set, cls) => {
      box.innerHTML = '';
      for (const [k, label] of items) {
        const b = document.createElement('button');
        b.className = cls + (k === cur ? ' on' : '');
        b.innerHTML = label;
        b.onclick = () => { set(k); tabs(); load(); };
        box.appendChild(b);
      }
    };
    mk($('rk-mode'), [['s', `<b>${G.Icons.html('user', 16)} Solo</b>`], ['g', `<b>${G.Icons.html('friends', 16)} Grupo</b>`]],
       mode, k => { mode = k; }, 'gen-tab');
    mk($('rk-metric'), [['t', 'Longest time survived'], ['k', 'Most kills']], metric, k => {
      metric = k;
      if (k === 'k' && dex) { dex = null; $('rk-poke').value = ''; $('rk-clear').classList.add('hidden'); }
    }, 'chip');
    $('rk-sub').textContent = metric === 'k' ? '· most kills' : '· tiempo aguantado';
    $('rk-poke').classList.toggle('hidden', metric === 'k');
    mk($('rk-period'), G.Ranking.PERIODS, period, k => {
      period = k;
      if (k !== 'a' && dex) { dex = null; $('rk-poke').value = ''; $('rk-clear').classList.add('hidden'); }
    }, 'chip');
    mk($('rk-scope'), [['all', 'Todos'], ['friends', 'Sólo amigos']], scope, k => { scope = k; }, 'chip');
  }

  const fmtK = n => (n || 0).toLocaleString('en-GB') + ' kills';
  const fmt = t => t >= 3600 ? Math.floor(t / 3600) + ':' + G.U.mmss(t % 3600).padStart(5, '0') : G.U.mmss(t);

  async function load() {
    const my = ++token;
    const list = $('rk-list');
    list.innerHTML = '<p class="sub">Cargando…</p>';
    $('rk-me').innerHTML = '';
    let rows = [], me = null;
    try {
      [rows, me] = await Promise.all([
        G.Ranking.top(eff(), period, dex, scope === 'friends'),
        G.Social.me ? G.Ranking.myRank(eff(), period, dex) : Promise.resolve(null)
      ]);
    } catch (e) {
      if (my !== token) return;
      list.innerHTML = '<p class="sub">No se pudo cargar el ranking (' + esc(e.code || e.message) + ').</p>';
      return;
    }
    if (my !== token) return;
    list.innerHTML = '';
    if (!rows.length) {
      list.innerHTML = '<p class="sub">Todavía no hay marcas aquí. ¡Sé el primero!</p>';
    }
    const uid = G.Social.uid;
    const b = G.Ranking.board(eff(), period, dex), done = G.Ranking.reported();
    rows.forEach((r, i) => list.appendChild(rowEl(r, i + 1, r.uids.includes(uid), b, done)));
    const val = metric === 'k' ? fmtK : fmt;

    // La frase se monta en cada idioma (traducirla por trozos sale rara).
    const en = G.I18n.lang === 'en';
    const pn = en ? { d: 'today', w: 'this week', m: 'this month', y: 'this year', a: 'of all time' }[period]
                  : { d: 'de hoy', w: 'de esta semana', m: 'de este mes', y: 'de este año', a: 'de siempre' }[period];
    const mon = dex ? G.DEX_BY[dex].name : '';
    const where = en ? (mode === 's' ? 'solo' : 'group') + (dex ? ' with ' + mon : '')
                     : (mode === 's' ? 'en solitario' : 'en grupo') + (dex ? ' con ' + mon : '');
    $('rk-me').innerHTML = !G.Social.me ? 'Elige un apodo (en Amigos) para salir en el ranking.'
      : me && me.out ? (en ? `<span translate="no">You're not in the top 50 ${where} ${pn} yet. Your exact rank is in All-time.</span>`
                           : `Aún no estás en el top 50 ${pn} ${where}. Tu puesto exacto está en Histórico.`)
      : me ? (en ? `<span translate="no">Your best ${where} rank ${pn}: <b class="gold">#${me.pos}</b> · ${val(me.t)}</span>`
                 : `Tu mejor puesto ${pn} ${where}: <b class="gold">#${me.pos}</b> · ${val(me.t)}`)
      : (en ? `<span translate="no">You don't have a ${where} record ${pn} yet.</span>` : `Aún no tienes marca ${pn} ${where}.`);
  }

  function rowEl(r, pos, mine, b, done) {
    const kills = metric === 'k';
    const el = document.createElement('div');
    el.className = 'rk-row' + (mine ? ' mine' : '') + (pos <= 3 ? ' top' + pos : '');
    el.insertAdjacentHTML('beforeend', `<span class="pos">${pos <= 3 ? G.Icons.html('trophy', 20) : ''}${pos}</span>`);
    const mons = document.createElement('span');
    mons.className = 'mons';
    r.dex.forEach((d, i) => { if (G.DEX_BY[d]) mons.appendChild(G.UI.spriteCanvas(d, 44, 40, { scale: 1, shiny: !!r.shiny[i] })); });
    el.appendChild(mons);
    el.insertAdjacentHTML('beforeend',
      `<span class="who"><b translate="no">${r.names.map((n, i) => `<a href="#" class="plink" data-u="${esc(r.uids[i] || '')}">${esc(n)}</a>`).join(' · ')}</b><small>Nv. ${r.lv || 1} · ${kills ? fmt(r.t) + ' survived' : (r.kills || 0).toLocaleString('es') + ' derrotados'}${period === 'a' && r.at ? ' · <span translate="no">' + new Date(r.at).toLocaleDateString('en-GB', { day: 'numeric', month: 'short', year: 'numeric' }) + '</span>' : ''}</small></span>
       <span class="time">${kills ? (r.kills || 0).toLocaleString('en-GB') : fmt(r.t)}</span>`);
    el.querySelectorAll('.plink').forEach(a => { a.onclick = e => { e.preventDefault(); G.ProfileUI.show(a.dataset.u); }; });
    // Reportar una marca sospechosa (no la tuya). Lo revisa el admin (mod-ui.js).
    if (!mine && G.Social.me) {
      const rep = document.createElement('button');
      const sent = done.has(b + '__' + r.id);
      rep.className = 'rk-rep' + (sent ? ' sent' : '');
      rep.title = sent ? 'Ya la has reportado' : 'Reportar marca sospechosa';
      rep.innerHTML = G.Icons.html('flag', 16);
      rep.onclick = async () => {
        if (rep.classList.contains('sent')) { G.UI.toast('Ya has reportado esta marca'); return; }
        if (!confirm('¿Reportar la marca de ' + r.names.join(', ') + ' como trampa?')) return;
        rep.classList.add('sent'); rep.title = 'Ya la has reportado';
        await G.Ranking.report(b, r);
        G.UI.toast('Gracias: la revisaremos');
      };
      el.appendChild(rep);
    } else el.appendChild(document.createElement('span'));
    return el;
  }

  return { init, open };
})();

;
/* js/ui/mod-ui.js */
/* ============ mod-ui.js — moderación del ranking (pantalla oculta) ============
 * Sólo la ve la cuenta de moderación (G.Ranking.isAdmin, y firestore.rules
 * admin(): aunque alguien abriera esta pantalla, el servidor no le dejaría
 * hacer nada). Se abre con el botón "Moderación" del ranking.
 *
 *   Reportes          marcas reportadas por los jugadores, las más reportadas
 *                     primero: borrar la marca, banear (no puede volver a
 *                     subir marcas, y se borra su marca de todas las tablas de
 *                     ahora) o descartar el reporte.
 *   Baneados          las cuentas baneadas del ranking; se pueden desbanear.
 */
G.ModUI = (() => {
  const $ = G.UI.$;
  const esc = s => String(s).replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
  let tab = 'rep';

  function init() {
    $('mod-back').onclick = () => G.RankingUI.open();
    $('mod-purge').onclick = async () => {
      if (!confirm('Remove ALL entries over 1 hour from the leaderboard (all boards)? This cannot be undone.')) return;
      const b = $('mod-purge');
      b.disabled = true;
      try {
        const r = await G.Ranking.purgeAbove(3600, (i, n) => { b.textContent = 'Checking ' + i + ' / ' + n + '…'; });
        G.UI.toast('Removed ' + r.rows + ' entries over 1 hour (' + r.boards + ' boards)', 5000);
      } catch (e) { G.UI.toast('Failed: ' + (e.code || e.message), 5000); }
      b.disabled = false; b.textContent = 'Remove entries over 1 hour';
      render();
    };
    document.querySelectorAll('#mod-tabs .tab').forEach(t => { t.onclick = () => { tab = t.dataset.tab; render(); }; });
  }

  function open() {
    if (!G.Ranking.isAdmin()) return;
    G.UI.show('scr-mod', true);
    render();
  }

  const fmt = t => G.U.mmss(t || 0);
  const btn = (label, cls, fn) => { const b = document.createElement('button'); b.className = 'btn small ' + cls; b.textContent = label; b.onclick = fn; return b; };

  async function render() {
    document.querySelectorAll('#mod-tabs .tab').forEach(t => t.classList.toggle('on', t.dataset.tab === tab));
    const list = $('mod-list');
    list.innerHTML = '<p class="sub">Loading…</p>';
    try {
      if (tab === 'rep') await renderReports(list);
      else await renderMarked(list);
    } catch (e) {
      list.innerHTML = '<p class="sub">Could not load (' + esc(e.code || e.message) + ').</p>';
    }
  }

  /** "s_w2026-42" -> "Solo · Semana" */
  function boardName(b) {
    const [m, p] = b.split('_');
    const mode = m === 'g' ? 'Group' : 'Solo';
    const per = p.startsWith('d') ? 'Today' : p.startsWith('w') ? 'Week' : p.startsWith('m') ? 'Month' : 'All time';
    const dex = (b.match(/_p(\d+)$/) || [])[1];
    return mode + ' · ' + per + (dex && G.DEX_BY[dex] ? ' · only ' + G.DEX_BY[dex].name : '');
  }
  // Con la Sentencia de Arceus (minuto 30) casi nadie pasa de ~32-33 min.
  const SUSPECT_T = 33 * 60;

  async function renderReports(list) {
    const groups = await G.Ranking.reports();
    list.innerHTML = groups.length ? '' : '<p class="sub">No reports.</p>';
    for (const g of groups) {
      const row = document.createElement('div');
      row.className = 'rk-row mod-row rep';
      const mode = g.board.startsWith('g_') ? 'g' : 's';
      // Lo que se ve de la marca ahora en su tabla (nivel, derrotados, Pokémon).
      const info = await G.Ranking.entryInfo(g.board, g.e).catch(() => null);
      const t = info ? info.t : g.t;
      const sus = t > SUSPECT_T;
      const mons = document.createElement('span');
      mons.className = 'mons';
      if (info) info.dex.forEach((d, i) => { if (G.DEX_BY[d]) mons.appendChild(G.UI.spriteCanvas(d, 44, 40, { scale: 1, shiny: !!(info.shiny || [])[i] })); });
      row.innerHTML = `<span class="pos" title="times reported">${g.n}×</span>`;
      row.appendChild(mons);
      row.insertAdjacentHTML('beforeend', `<span class="who"><b translate="no">${g.names.map(esc).join(' · ')}</b>
          <small>${esc(boardName(g.board))}${info ? ' · Lv. ' + (info.lv || 1) + ' · ' + (info.kills || 0).toLocaleString('en') + ' defeated' : ' · no longer in the top 50'}</small>
          ${sus ? '<small class="mod-warn">Over 33 min: almost impossible with the Judgment of Arceus</small>' : ''}</span>
        <span class="time${sus ? ' mod-warn' : ''}">${fmt(t)}</span>`);
      const acts = document.createElement('span');
      acts.className = 'mod-acts';
      const busy = async (fn, msg) => {
        acts.querySelectorAll('button').forEach(b => { b.disabled = true; });
        try { await fn(); G.UI.toast(msg); row.remove(); }
        catch (e) { G.UI.toast('Failed: ' + (e.code || e.message)); acts.querySelectorAll('button').forEach(b => { b.disabled = false; }); }
      };
      acts.append(
        btn('Delete entry', 'ghost', () => busy(async () => {
          await G.Ranking.removeEverywhere(g.e, mode, [], g.board);
          await G.Ranking.dismiss(g.ids);
        }, 'Entry deleted')),
        btn('Ban', 'danger', () => {
          if (!confirm('Ban ' + g.names.join(', ') + '? They will no longer be able to appear on the leaderboard, and their entry is deleted.')) return;
          busy(async () => {
            const uids = g.e.split('_');
            for (const u of uids) await G.Ranking.setMarked(u, true).catch(() => {});
            await G.Ranking.removeEverywhere(g.e, mode, [], g.board);
            await G.Ranking.dismiss(g.ids);
          }, 'Banned');
        }),
        btn('Dismiss', 'ghost', () => busy(() => G.Ranking.dismiss(g.ids), 'Report dismissed'))
      );
      row.appendChild(acts);
      list.appendChild(row);
    }
  }

  async function renderMarked(list) {
    const accs = await G.Ranking.markedAccounts();
    list.innerHTML = accs.length ? '' : '<p class="sub">No banned accounts.</p>';
    for (const a of accs) {
      const row = document.createElement('div');
      row.className = 'rk-row mod-row';
      row.innerHTML = `<span class="pos"></span>
        <span class="who"><b translate="no">${esc(a.name)}</b><small translate="no">${a.coins.toLocaleString('en')} coins · ${a.t1} tickets · ${a.t10} ×10 · ${a.owned} Pokémon · ${esc(a.uid)}</small></span>`;
      const acts = document.createElement('span');
      acts.className = 'mod-acts';
      acts.append(btn('Unban', 'ghost', async () => {
        try { await G.Ranking.setMarked(a.uid, false); G.UI.toast('Unbanned'); row.remove(); }
        catch (e) { G.UI.toast('Failed: ' + (e.code || e.message)); }
      }));
      row.appendChild(acts);
      list.appendChild(row);
    }
  }

  return { init, open };
})();

;
/* js/ui/goals-ui.js */
/* ============ goals-ui.js — misiones, logros y perfil ============
 * Una pantalla con tres pestañas:
 *   Misiones  3 diarias + 2 semanales, con barra, premio y botón de recoger
 *   Logros    medallas por categoría; los legendarios, uno a uno con su sprite
 *   Perfil    tus 3 favoritos y tu título; vista previa del perfil público
 * y la ventana del perfil público de cualquier jugador (G.ProfileUI.show).
 */
(() => {
  const $ = G.UI.$;
  const esc = s => String(s).replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
  const fmt = t => (t >= 3600 ? Math.floor(t / 3600) + ':' + G.U.mmss(t % 3600).padStart(5, '0') : G.U.mmss(t));

  // ======================= PANTALLA =======================

  G.GoalsUI = (() => {
    let tab = 'missions', cat = 'coleccion';

    function init() {
      document.querySelectorAll('#goals-tabs .tab').forEach(t => {
        t.onclick = () => { tab = t.dataset.tab; render(); };
      });
    }

    function open(t) {
      if (t) tab = t;
      G.UI.show('scr-goals', true);
      G.Progress.ensure(G.DB.save);
      G.Progress.checkAch();
      render();
    }

    function render() {
      document.querySelectorAll('#goals-tabs .tab').forEach(t => t.classList.toggle('on', t.dataset.tab === tab));
      const box = $('goals-body');
      box.innerHTML = '';
      if (tab === 'missions') missions(box);
      else if (tab === 'ach') achievements(box);
      else if (tab === 'history') history(box);
      else profile(box);
    }

    // ---------------- history (last 100 runs) ----------------

    let histShown = 20, histOpen = null;
    const fmtDate = ms => new Date(ms).toLocaleString('en-GB', { day: 'numeric', month: 'short', year: 'numeric', hour: '2-digit', minute: '2-digit' });
    const num = n => (n || 0).toLocaleString('en-GB');

    function history(box) {
      const list = G.DB.save.history || [];
      box.insertAdjacentHTML('beforeend', `<div class="row between goals-h"><h3>Run history</h3>
        <span class="sub" translate="no">Last ${G.DB.HISTORY_MAX} runs · ${list.length} saved</span></div>`);
      if (!list.length) { box.insertAdjacentHTML('beforeend', '<p class="sub">No runs yet. Finish a run and it will show up here.</p>'); return; }
      const best = Math.max(...list.map(e => e.t));
      list.slice(0, histShown).forEach(e => {
        const mon = G.DEX_BY[e.d];
        const el = document.createElement('div');
        el.className = 'hist-run' + (histOpen === e.id ? ' open' : '');
        const mates = e.mt || [];
        el.innerHTML = `
          <div class="hist-head">
            <span class="hist-mon"></span>
            <div class="hist-main">
              <b translate="no">${esc(mon ? mon.name : '?')}${e.sh ? ' ' + G.Icons.html('shiny', 12) : ''}${e.ar ? ' ' + G.Icons.html('star', 14) : ''}</b>
              <small translate="no">${fmtDate(e.id)}</small>
            </div>
            <div class="hist-nums" translate="no">
              <span class="hist-t${e.t === best ? ' best' : ''}">${fmt(e.t)}</span>
              <small>Lv. ${e.lv} · ${num(e.k)} kills</small>
            </div>
            <span class="hist-tag ${e.g ? 'grp' : ''}" translate="no">${e.g ? 'Group' : 'Solo'}</span>
          </div>
          <div class="hist-detail">
            <div class="hist-grid">
              <div><span>Result</span><b>${e.x ? 'Fainted' : 'Left the run'}</b></div>
              <div><span>Bosses beaten</span><b>${num(e.b)}</b></div>
              <div><span>Coins earned</span><b>${num(e.c)}</b></div>
              <div><span>Damage dealt</span><b>${num(e.dd)}</b></div>
              <div><span>Damage taken</span><b>${num(e.dt)}</b></div>
              <div><span>Held item</span><b>${e.it && G.Items.BY[e.it] ? esc(G.Items.BY[e.it].name) : '—'}</b></div>
              ${e.ar ? `<div style="grid-column:1/-1"><span>Arceus</span><b>${G.Icons.html('star', 14)} Reached Arceus: ${fmt(e.ar[0])} in the fight · ${e.ar[1]} legendaries beaten</b></div>` : ''}
            </div>
            <div class="hist-moves"><span>Moves</span>
              ${e.m.length ? e.m.map(([id, lv]) => `<i>${G.Icons.html('move:' + id, 16)} ${esc(G.Moves.BY_ID[id].name)} Lv.${lv}</i>`).join('') : '<i>—</i>'}</div>
            ${mates.length ? `<div class="hist-mates"><span>Teammates</span><div class="hist-mate-row"></div></div>` : ''}
          </div>`;
        el.querySelector('.hist-mon').appendChild(G.UI.spriteCanvas(e.d, 44, 40, { scale: 1, shiny: !!e.sh }));
        const mr = el.querySelector('.hist-mate-row');
        if (mr) mates.forEach(([n, d, sh]) => {
          const m = document.createElement('span');
          m.className = 'hist-mate';
          if (G.DEX_BY[d]) m.appendChild(G.UI.spriteCanvas(d, 32, 30, { scale: 1, shiny: !!sh }));
          m.insertAdjacentHTML('beforeend', `<b translate="no">${esc(n)}</b><small translate="no">${G.DEX_BY[d] ? esc(G.DEX_BY[d].name) : ''}</small>`);
          mr.appendChild(m);
        });
        el.querySelector('.hist-head').onclick = () => { histOpen = histOpen === e.id ? null : e.id; render(); };
        box.appendChild(el);
      });
      if (list.length > histShown) {
        const more = document.createElement('button');
        more.className = 'btn small ghost'; more.textContent = 'Show more (' + (list.length - histShown) + ' left)';
        more.onclick = () => { histShown += 20; render(); };
        box.appendChild(more);
      }
    }

    // ---------------- misiones ----------------

    function untilText(kind) {
      const now = new Date();
      // Medianoche (diarias) o lunes (semanales), hora de España aproximada por la del navegador.
      const end = new Date(now);
      end.setHours(24, 0, 0, 0);
      if (kind === 'w') { const add = (8 - (now.getDay() || 7)) % 7; end.setDate(end.getDate() + add); }
      const mins = Math.max(1, Math.round((end - now) / 60000));
      return mins >= 1440 ? Math.floor(mins / 1440) + ' d ' + Math.floor(mins % 1440 / 60) + ' h'
                          : Math.floor(mins / 60) + ' h ' + (mins % 60) + ' min';
    }

    function missions(box) {
      const M = G.DB.save.missions;
      const section = (title, list, weekly) => {
        box.insertAdjacentHTML('beforeend', `<div class="row between goals-h"><h3>${title}</h3>
          <span class="sub">Se renuevan en ${untilText(weekly ? 'w' : 'd')}</span></div>`);
        list.forEach((m, i) => {
          const d = G.MissionDefs.BY[m.id];
          const done = G.Progress.done(m);
          const el = document.createElement('div');
          el.className = 'mission' + (m.claimed ? ' claimed' : done ? ' ready' : '');
          const pct = Math.min(100, m.prog / m.goal * 100);
          el.innerHTML = `
            <div class="m-txt"><b>${esc(G.Progress.text(m))}</b>
              <div class="bar"><i style="width:${pct}%"></i></div>
              <small>${Math.min(m.prog, m.goal).toLocaleString('es')} / ${m.goal.toLocaleString('es')}</small></div>
            <div class="m-rw">${G.Progress.rewardText(d.reward)}</div>`;
          const btn = document.createElement('button');
          if (m.claimed) { btn.className = 'btn small'; btn.disabled = true; btn.textContent = 'Recogido'; }
          else if (done) {
            btn.className = 'btn small gold'; btn.textContent = 'Recoger'; btn.dataset.sfx = 'none';
            btn.onclick = () => { if (G.Progress.claim(m, weekly)) { G.Audio.sfx('buy'); G.UI.toast('¡Premio recogido!'); render(); } };
          } else if (!weekly && !M.rerolled) {
            btn.className = 'btn small ghost'; btn.textContent = 'Cambiar';
            btn.title = 'Cambia esta misión por otra (una vez al día)';
            btn.onclick = () => { if (G.Progress.reroll(i)) render(); };
          } else { btn.className = 'btn small ghost'; btn.disabled = true; btn.textContent = 'En curso'; }
          el.appendChild(btn);
          box.appendChild(el);
        });
      };
      section('Diarias', M.daily, false);
      section('Semanales', M.weekly, true);
    }

    // ---------------- logros ----------------

    function achievements(box) {
      const s = G.DB.save;
      const all = G.AchDefs.LIST;
      const got = all.filter(a => s.ach && s.ach[a.id]).length;
      const chips = document.createElement('div');
      chips.className = 'filters';
      for (const [k, label] of G.AchDefs.CATS) {
        const list = all.filter(a => a.cat === k);
        const n = list.filter(a => s.ach && s.ach[a.id]).length;
        const b = document.createElement('button');
        b.className = 'chip' + (k === cat ? ' on' : '');
        b.textContent = `${label} ${n}/${list.length}`;
        b.onclick = () => { cat = k; render(); };
        chips.appendChild(b);
      }
      box.insertAdjacentHTML('beforeend', `<p class="sub">${got} de ${all.length} logros · títulos: ${G.Progress.titles().length}</p>`);
      box.appendChild(chips);

      const list = all.filter(a => a.cat === cat && !a.dex);
      const grid = document.createElement('div');
      grid.className = 'ach-grid';
      for (const a of list) grid.appendChild(achCard(a, s));
      box.appendChild(grid);

      // Legendarios: uno a uno, con su sprite (en sombra si aún no le has vencido).
      if (cat === 'legendarios') {
        const legs = all.filter(a => a.dex);
        const beaten = legs.filter(a => s.legends && s.legends[a.dex]).length;
        box.insertAdjacentHTML('beforeend', `<h3 style="margin:14px 0 6px">Legendarios vencidos ${beaten} / ${legs.length}</h3>`);
        const lg = document.createElement('div');
        lg.className = 'leg-grid';
        for (const a of legs) {
          const ok = !!(s.legends && s.legends[a.dex]);
          const c = document.createElement('div');
          c.className = 'leg-cell' + (ok ? ' ok' : '');
          c.title = a.name + (ok ? ' · ¡vencido!' : '');
          c.appendChild(G.UI.spriteCanvas(a.dex, 64, 56, { scale: 1, silhouette: !ok, shadow: ok }));
          c.insertAdjacentHTML('beforeend', `<small>${ok ? esc(G.DEX_BY[a.dex].name) : '???'}</small>`);
          lg.appendChild(c);
        }
        box.appendChild(lg);
      }
    }

    function achCard(a, s) {
      const ok = !!(s.ach && s.ach[a.id]);
      const v = Math.min(a.goal, a.value(s));
      const el = document.createElement('div');
      el.className = 'ach' + (ok ? ' ok' : '');
      el.innerHTML = `${G.Icons.html(ok ? 'medal' + a.tier : 'medalOff', 36)}
        <div class="a-txt"><b>${esc(a.name)}</b><small>${esc(a.desc)}</small>
          ${ok ? '' : `<div class="bar"><i style="width:${v / a.goal * 100}%"></i></div>`}
          <div class="a-rw">${ok ? '¡Conseguido!' : v.toLocaleString('es') + ' / ' + a.goal.toLocaleString('es')} · ${G.Progress.rewardText(a.reward)}
          ${a.title ? ` · <span class="gold">Título: ${esc(a.title)}</span>` : ''}</div></div>`;
      return el;
    }

    // ---------------- perfil (editar) ----------------

    function profile(box) {
      const s = G.DB.save;
      s.profile = s.profile || { favs: [], title: '' };
      const P = s.profile;
      box.insertAdjacentHTML('beforeend', `<p class="sub">${G.DB.online ? 'Así te ven los demás jugadores (desde el ranking y la lista de amigos).'
        : 'Tu perfil se publica cuando juegas con una cuenta online.'}</p>
        <h3>Tus 3 Pokémon favoritos</h3>`);
      const favs = document.createElement('div');
      favs.className = 'fav-slots';
      for (let i = 0; i < 3; i++) {
        const f = P.favs[i];
        const slot = document.createElement('div');
        slot.className = 'fav-slot';
        if (f && G.DEX_BY[f.dex]) {
          slot.appendChild(G.UI.spriteCanvas(f.dex, 120, 100, { scale: 2, lively: true, shiny: !!f.shiny }));
          slot.insertAdjacentHTML('beforeend', `<b>${f.shiny ? G.Icons.html('shiny', 12) + ' ' : ''}${esc(G.DEX_BY[f.dex].name)}</b>`);
        } else slot.innerHTML = '<span>Elegir</span>';
        slot.onclick = () => pickFav(i);
        favs.appendChild(slot);
      }
      box.appendChild(favs);

      const titles = G.Progress.titles();
      // Titles are Spanish keys that the page translates on screen. The dropdown used to save the
      // translated text, which never matched again. Fix any title saved that way.
      if (P.title && !titles.includes(P.title)) {
        const orig = titles.find(t => G.I18n.t(t) === P.title);
        if (orig) { P.title = orig; G.DB.commit(); if (G.Social.me) G.Social.publishProfile(true); }
      }
      box.insertAdjacentHTML('beforeend', `<h3 style="margin-top:14px">Título</h3>`);
      const sel = document.createElement('select');
      sel.className = 'field';
      sel.style.maxWidth = '320px';
      sel.innerHTML = `<option value="">(sin título)</option>` + titles.map(t => `<option value="${esc(t)}" ${t === P.title ? 'selected' : ''}>${esc(t)}</option>`).join('');
      sel.onchange = () => { P.title = sel.value; save(); };
      box.appendChild(sel);
      if (!titles.length) box.insertAdjacentHTML('beforeend', '<p class="note">Consigue logros para desbloquear títulos.</p>');

      // Banner, border and chat name colour.
      const C = G.Cosmetics;
      const pick = (title, list, key, swatch) => {
        box.insertAdjacentHTML('beforeend', `<h3 style="margin-top:14px">${title}</h3>`);
        const row = document.createElement('div');
        row.className = 'cos-row';
        for (const it of list) {
          const ok = C.unlocked(it);
          const b = document.createElement('button');
          b.className = 'cos-sw' + ((P[key] || '') === it.id ? ' on' : '') + (ok ? '' : ' locked');
          b.type = 'button';
          swatch(b, it);
          b.title = it.name + (ok ? '' : ' (locked): ' + C.hint(it));
          b.insertAdjacentHTML('beforeend', `<small>${esc(it.name)}</small>`);
          b.onclick = () => {
            if (!ok) { G.UI.toast(C.hint(it), 2600); G.Audio.sfx('error'); return; }
            P[key] = it.id; save(); render();
          };
          row.appendChild(b);
        }
        box.appendChild(row);
      };
      pick('Profile banner', C.BANNERS, 'banner', (b, it) => { b.style.setProperty('--bg', it.bg); b.classList.add('bn'); });
      pick('Profile border', C.FRAMES, 'frame', (b, it) => { b.classList.add('fr'); b.dataset.frame = it.id; if (it.color) b.style.setProperty('--fc', it.color); });
      box.insertAdjacentHTML('beforeend', `<h3 style="margin-top:14px">Chat name colour</h3>`);
      const cr = document.createElement('div');
      cr.className = 'cos-row';
      for (const c of C.NAME_COLORS) {
        const b = document.createElement('button');
        b.type = 'button';
        b.className = 'cos-col' + ((P.chatColor || '') === c ? ' on' : '');
        b.style.background = c || 'linear-gradient(135deg, #ffd23f 50%, #9fd4ff 50%)';
        b.title = c ? 'Use this colour' : 'Default (gold for you, blue for others)';
        b.onclick = () => { P.chatColor = c; save(); render(); };
        cr.appendChild(b);
      }
      box.appendChild(cr);
      const sample = document.createElement('p');
      sample.className = 'cm cos-sample'; sample.setAttribute('translate', 'no');
      sample.innerHTML = `<b style="${C.chatColor() ? 'color:' + C.chatColor() : ''}">${esc(G.Social.me ? G.Social.me.name : 'You')}</b> <span class="cm-t">This is how your name looks in chat</span>`;
      box.appendChild(sample);

      const prev = document.createElement('button');
      prev.className = 'btn gold'; prev.style.marginTop = '16px';
      prev.textContent = 'Ver mi perfil público';
      prev.onclick = () => G.ProfileUI.showData(G.Social.profileData());
      box.appendChild(prev);
    }

    function pickFav(i) {
      const s = G.DB.save;
      const box = $('goals-body');
      box.innerHTML = `<div class="row between"><h3>Elige el favorito ${i + 1}</h3>
        <button class="btn small ghost" id="fav-back">Volver</button></div>
        <input class="field" id="fav-q" placeholder="Buscar por nombre" style="max-width:320px;margin:6px 0 10px">
        <div class="grid" id="fav-grid"></div>`;
      $('fav-back').onclick = () => { tab = 'profile'; render(); };
      // All owned Pokémon (and their shinies), added to the grid 120 at a time as you scroll
      // (it used to stop at the first 120, so later generations never showed up).
      const PAGE = 120;
      const fill = q => {
        const g = $('fav-grid');
        g.innerHTML = '';
        g.scrollTop = 0;
        const items = [];
        const mons = Object.keys(s.owned).map(Number).filter(d => G.DEX_BY[d] && (!q || G.DEX_BY[d].name.toLowerCase().includes(q)));
        for (const d of mons) for (const shiny of G.DB.ownsShiny(d) ? [false, true] : [false]) items.push([d, shiny]);
        let shown = 0;
        const more = () => {
          for (const [d, shiny] of items.slice(shown, shown + PAGE)) {
            const c = document.createElement('div');
            c.className = 'cell';
            c.appendChild(G.UI.spriteCanvas(d, 92, 80, { scale: 2, shiny }));
            c.insertAdjacentHTML('beforeend', `<b>${shiny ? G.Icons.html('shiny', 12) + ' ' : ''}${esc(G.DEX_BY[d].name)}</b>`);
            c.onclick = () => {
              s.profile.favs = (s.profile.favs || []).slice();
              s.profile.favs[i] = { dex: d, shiny };
              s.profile.favs = s.profile.favs.filter(Boolean).slice(0, 3);
              save(); tab = 'profile'; render();
            };
            g.appendChild(c);
          }
          shown = Math.min(items.length, shown + PAGE);
        };
        g.onscroll = () => { if (shown < items.length && g.scrollTop + g.clientHeight > g.scrollHeight - 400) more(); };
        more();
        // Tall screens: keep adding until the grid actually scrolls.
        while (shown < items.length && g.scrollHeight <= g.clientHeight + 50) more();
      };
      $('fav-q').oninput = () => fill($('fav-q').value.trim().toLowerCase());
      fill('');
    }

    function save() {
      G.DB.commit();
      if (G.Social.me) G.Social.publishProfile(true);
      G.Audio.sfx('confirm');
    }

    return { init, open, render };
  })();

  // ======================= PERFIL PÚBLICO =======================

  G.ProfileUI = (() => {
    function init() {
      $('prof-close').onclick = close;
      $('scr-profile').onclick = e => { if (e.target.id === 'scr-profile') close(); };
    }
    function close() { $('scr-profile').classList.add('hidden'); }

    /** Abre el perfil de otro jugador por su uid. */
    async function show(uid) {
      if (!uid) return;
      if (uid === G.Social.uid) { showData(G.Social.profileData()); return; }
      $('prof-body').innerHTML = '<p class="sub">Cargando…</p>';
      $('scr-profile').classList.remove('hidden');
      const d = await G.Social.getProfile(uid);
      if (!d) { $('prof-body').innerHTML = '<p class="sub">Este jugador aún no tiene perfil.</p>'; return; }
      showData(d);
    }

    function showData(d) {
      const b = d.best || {};
      const body = $('prof-body');
      body.innerHTML = `
        <div class="prof-head" id="prof-head"><h2 translate="no">${esc(d.name || '???')}</h2>${d.title ? `<span class="prof-title">${esc(d.title)}</span>` : ''}</div>
        <div class="fav-slots view" id="prof-favs"></div>
        <div class="prof-marks">
          <div><span>Mejor tiempo</span><b>${fmt(b.solo || 0)}</b></div>
          <div><span>En grupo</span><b>${fmt(b.group || 0)}</b></div>
          <div><span>Nivel máximo</span><b>${b.level || 0}</b></div>
          <div><span>Jefes</span><b>${(b.bosses || 0).toLocaleString('es')}</b></div>
          <div><span>Legendarios</span><b>${b.legends || 0}</b></div>
          <div><span>Derrotados</span><b>${(b.kills || 0).toLocaleString('es')}</b></div>
        </div>
        <h3>Medallas <span class="sub">${b.medals || 0}</span></h3>
        <div class="prof-medals" id="prof-medals"></div>`;
      G.Cosmetics.apply($('scr-profile').querySelector('.profile-box'), $('prof-head'), d);
      const favs = $('prof-favs');
      for (const f of (d.favs || []).slice(0, 3)) {
        if (!G.DEX_BY[f.dex]) continue;
        const slot = document.createElement('div');
        slot.className = 'fav-slot';
        slot.appendChild(G.UI.spriteCanvas(f.dex, 120, 100, { scale: 2, lively: true, shiny: !!f.shiny }));
        slot.insertAdjacentHTML('beforeend', `<b>${f.shiny ? G.Icons.html('shiny', 12) + ' ' : ''}${esc(G.DEX_BY[f.dex].name)}</b>`);
        favs.appendChild(slot);
      }
      if (!favs.children.length) favs.innerHTML = '<p class="sub">Sin favoritos todavía.</p>';
      const med = $('prof-medals');
      for (const id of d.medals || []) {
        const a = G.AchDefs.BY[id];
        if (!a) continue;
        const m = document.createElement('div');
        m.className = 'pm';
        m.title = a.name;
        if (a.dex) m.appendChild(G.UI.spriteCanvas(a.dex, 48, 40, { scale: 1 }));
        else m.innerHTML = G.Icons.html('medal' + a.tier, 36);
        m.insertAdjacentHTML('beforeend', `<small>${esc(a.name)}</small>`);
        med.appendChild(m);
      }
      if (!med.children.length) med.innerHTML = '<p class="sub">Aún sin medallas.</p>';
      $('scr-profile').classList.remove('hidden');
    }

    return { init, show, showData };
  })();
})();

;
/* js/ui/settings-ui.js */
/* ============ settings-ui.js — pantalla de Ajustes (PC y móvil) ============
 * Se abre por encima de lo que haya (menú o pausa) y al cerrar vuelve ahí.
 * Pestañas: Sonido · Gráficos · Controles · Cuenta · Acerca de.
 * Los ajustes son de este dispositivo (G.Settings / G.Audio en el navegador).
 */
G.SettingsUI = (() => {
  const $ = G.UI.$;
  const esc = s => String(s).replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
  const VERSION = '1.2 · 2026-10-09';
  const REPO = 'https://github.com/Dippydoco/Megamon';
  let tab = 'sound';

  function init() {
    document.querySelectorAll('#set-tabs .gen-tab').forEach(b => { b.onclick = () => { tab = b.dataset.t; render(); }; });
    $('set-close').onclick = close;
    $('btn-settings').innerHTML = G.Icons.html('gear', 20);
    $('btn-settings').onclick = () => open();
    $('btn-pause-settings').onclick = () => open('sound');
    // Pantalla completa (si el navegador la permite; en iPhone, cómo conseguirla).
    if (canFull() || iosTip()) {
      $('btn-full').classList.remove('hidden');
      $('btn-full').innerHTML = G.Icons.html('full', 20);
      $('btn-full').onclick = toggleFull;
    }
  }

  function open(t) {
    if (t) tab = t;
    $('scr-settings').classList.remove('hidden');
    render();
  }
  function close() { $('scr-settings').classList.add('hidden'); }
  const isOpen = () => !$('scr-settings').classList.contains('hidden');

  // ---------------- pantalla completa ----------------
  function canFull() { return !!(document.fullscreenEnabled || document.webkitFullscreenEnabled); }
  function isFull() { return !!(document.fullscreenElement || document.webkitFullscreenElement); }
  // iPhone: Safari no deja poner una web a pantalla completa (por eso a veces
  // no salía la opción). Sí se puede abriéndola desde la pantalla de inicio.
  const IOS = /iPhone|iPad|iPod/.test(navigator.userAgent) || (navigator.platform === 'MacIntel' && navigator.maxTouchPoints > 1);
  const standalone = () => !!navigator.standalone || (window.matchMedia && matchMedia('(display-mode: fullscreen), (display-mode: standalone)').matches);
  function iosTip() { return IOS && !canFull() && !standalone(); }
  const IOS_TIP = 'En iPhone, Safari no deja poner las webs a pantalla completa. Pulsa Compartir y luego "Añadir a pantalla de inicio": abriendo el juego desde ese icono se juega a pantalla completa.';
  function toggleFull() {
    if (!canFull()) { if (iosTip()) G.UI.toast(IOS_TIP, 9000); return; }
    if (isFull()) (document.exitFullscreen || document.webkitExitFullscreen).call(document);
    else {
      const el = document.documentElement;
      const p = (el.requestFullscreen || el.webkitRequestFullscreen).call(el);
      // En móvil, además se intenta fijar la pantalla en horizontal.
      if (p && p.then) p.then(() => { try { screen.orientation.lock('landscape').catch(() => {}); } catch (e) { /* nada */ } }).catch(() => {});
    }
    setTimeout(() => { if (isOpen()) render(); }, 300);
  }

  // ---------------- piezas ----------------
  function section(title, sub) { return `<h3 class="set-h">${esc(title)}</h3>${sub ? `<p class="sub">${sub}</p>` : ''}`; }
  function toggle(key, label, desc) {
    const on = !!G.Settings.get(key);
    return `<div class="set-row"><div class="grow"><b>${esc(label)}</b><small>${esc(desc)}</small></div>
      <button class="btn small switch ${on ? 'gold' : ''}" data-k="${key}">${on ? 'Sí' : 'No'}</button></div>`;
  }
  function choice(key, opts) {
    const cur = G.Settings.get(key);
    return `<div class="chips set-chips">${opts.map(([v, l]) => `<button class="chip ${v === cur ? 'on' : ''}" data-k="${key}" data-v="${v}">${esc(l)}</button>`).join('')}</div>`;
  }

  function render() {
    document.querySelectorAll('#set-tabs .gen-tab').forEach(b => b.classList.toggle('on', b.dataset.t === tab));
    const box = $('set-body');
    box.scrollTop = 0;
    if (tab === 'sound') {
      box.innerHTML = section('Sonido') + '<div id="set-sound" class="sound-inline"></div>';
      G.UI.soundControls($('set-sound'));
    } else if (tab === 'gfx') {
      const auto = ['baja', 'media', 'alta'][G.Settings.autoLevel];
      box.innerHTML = section('Idioma', 'El juego se recarga al cambiarlo.')
        + `<div class="chips set-chips" translate="no">${[['es', 'Español'], ['en', 'English']].map(([v, l]) =>
             `<button class="chip ${G.I18n.lang === v ? 'on' : ''}" data-lang="${v}">${l}</button>`).join('')}</div>`
        + section('Calidad', 'Cuántos efectos y partículas se dibujan. <b>Auto</b> la baja sola si el juego va a tirones (ahora: ' + auto + ').')
        + choice('quality', [['auto', 'Auto'], ['high', 'Alta'], ['mid', 'Media'], ['low', 'Baja']])
        + section('Pantalla')
        + toggle('dmgNumbers', 'Números de daño', 'Los números que salen al golpear y al recibir daño.')
        + `<div class="set-row"><div class="grow"><b>Damage number size</b><small>How big the numbers are when you hit enemies.</small></div></div>`
        + choice('dmgSize', [[0.8, 'Small'], [1, 'Normal'], [1.35, 'Large']])
        + `<div class="set-row"><div class="grow"><b>Which hits show a number</b><small>"Important only" hides the small hits and keeps critical, super effective and boss hits (and the damage you take).</small></div></div>`
        + choice('dmgShow', [['all', 'All hits'], ['big', 'Important only']])
        + `<div class="set-row"><div class="grow"><b>Damage number colours</b><small>Colours show how effective a hit was. "White" keeps every number plain.</small></div></div>`
        + choice('dmgColor', [['type', 'Coloured'], ['white', 'White']])
        + toggle('calm', 'Menos sacudidas y destellos', 'La cámara tiembla menos y los fogonazos son suaves.')
        + toggle('fps', 'Mostrar FPS', 'Fotogramas por segundo, en la esquina de abajo.')
        + (canFull() ? `<div class="set-row"><div class="grow"><b>Pantalla completa</b><small>Sin barras del navegador.</small></div>
             <button class="btn small" id="set-full">${isFull() ? 'Salir' : 'Activar'}</button></div>`
           : iosTip() ? `<div class="set-row"><div class="grow"><b>Pantalla completa</b><small>${esc(IOS_TIP)}</small></div></div>` : '');
    } else if (tab === 'ctl') {
      box.innerHTML = section('En móvil o tablet')
        + `<p class="sub">Pon el dedo en cualquier parte y arrastra para moverte: el joystick aparece donde tocas. Toca un ataque de abajo para cambiarlo y el botón de arriba a la derecha para pausar. Se juega en horizontal.</p>`
        + `<div class="set-row"><div class="grow"><b>Tamaño del joystick</b><small>Cuánto hay que arrastrar el dedo.</small></div></div>`
        + choice('stick', [[0.8, 'Pequeño'], [1, 'Normal'], [1.25, 'Grande']])
        + `<div class="set-row"><div class="grow"><b>Colocar los botones</b><small>Pon los ataques, la pausa y el joystick (fijo, si quieres) donde quieras de la pantalla.</small></div>
             <button class="btn small" id="set-layout">Colocar</button></div>`
        + section('En PC')
        + toggle('mouseStick', 'Mover con el ratón', 'Mantén pulsado el botón izquierdo y arrastra: aparece un joystick donde pulsas. Suelta para parar.')
        + toggle('mouseLock', 'Joystick del ratón fijo', 'El joystick se queda donde pulsaste y no te sigue al arrastrar lejos. Suelta y vuelve a pulsar para colocarlo en otro sitio.')
        + `<div class="keys">
             <div><kbd>W</kbd><kbd>A</kbd><kbd>S</kbd><kbd>D</kbd> o flechas</div><span>moverse</span>
             <div><kbd>1</kbd>–<kbd>4</kbd> o clic en el icono</div><span>elegir ataque</span>
             <div><kbd>Q</kbd> / <kbd>E</kbd></div><span>ataque anterior / siguiente</span>
             <div><kbd>Esc</kbd> o <kbd>P</kbd></div><span>pausa</span>
             <div><kbd>1</kbd>–<kbd>3</kbd></div><span>elegir carta al subir de nivel</span>
           </div>`;
    } else if (tab === 'acc') {
      renderAccount(box);
    } else if (tab === 'code') {
      renderCode(box);
    } else {
      box.innerHTML = `<div class="about-logo">Megamon</div><p class="sub center">Versión ${esc(VERSION)} · ${esc(G.UI.buildLabel())}</p>`
        + `<p class="sub">Juego de fans <b>gratuito y sin ánimo de lucro</b>: sin anuncios ni compras. Pokémon y sus personajes son propiedad de Nintendo, Creatures y GAME FREAK; este proyecto no está afiliado a ellos.</p>`
        + section('Créditos')
        + `<ul class="credits">
             <li><b>Sprites:</b> PMD SpriteCollab y sus artistas (CC BY-NC 4.0).</li>
             <li><b>Datos de los Pokémon:</b> PokéAPI.</li>
             <li><b>Música y sonidos:</b> originales, generados por el propio juego.</li>
             <li><b>Fuente:</b> Pixelify Sans (OFL).</li>
           </ul>`
        + `<div class="row wrap" style="justify-content:center;gap:8px">
             ${window.PS_PAGES ? `<a class="btn small" href="en/guide/" target="_blank">Guía y preguntas</a>
             <a class="btn small" href="${G.I18n.lang === 'en' ? 'en/pokedex/' : 'pokedex/'}" target="_blank">Pokédex</a>` : ''}
             <button class="btn small" data-legal>Aviso legal y privacidad</button>
             <a class="btn small" href="${REPO}" target="_blank" rel="noopener">Código (GitHub)</a>
           </div>`;
    }
    wire(box);
  }

  /** Canjear un código (js/systems/redeem.js): tickets y/o monedas, una vez por cuenta. */
  function renderCode(box) {
    if (G.DB.guest) {
      box.innerHTML = section('Código', 'Como <b>invitado</b> no se guarda el progreso, así que no se pueden canjear códigos. Crea una cuenta o entra con la tuya.')
        + `<button class="btn gold" id="set-login">Crear cuenta o entrar</button>`;
      return;
    }
    box.innerHTML = section('Código', 'Escribe un código para canjearlo. Cada código se puede usar una vez por cuenta.')
      + `<div class="row wrap" style="gap:8px;align-items:center">
           <input class="field" id="code-in" type="text" maxlength="40" placeholder="Código" autocomplete="off" autocapitalize="characters" spellcheck="false" style="flex:1;min-width:180px">
           <button class="btn gold" id="code-go">Canjear</button>
         </div><p class="note" id="code-msg"></p>`;
    const input = $('code-in'), msg = $('code-msg');
    const go = () => {
      const r = G.Redeem.redeem(input.value);
      if (!r.ok) { G.Audio.sfx('error'); msg.textContent = r.error; return; }
      G.Audio.sfx('confirm');
      input.value = '';
      if (r.demo !== undefined) {
        const t = r.demo ? 'Gacha demo mode is ON: pulls cost nothing and nothing is saved. Enter the code again to turn it off.' : 'Gacha demo mode is OFF.';
        msg.textContent = t; G.UI.toast(r.demo ? 'Gacha demo mode ON' : 'Gacha demo mode OFF');
        return;
      }
      msg.innerHTML = '¡Canjeado! Has recibido: ' + G.Progress.rewardText(r.reward);
      G.UI.toast('¡Código canjeado!');
    };
    $('code-go').onclick = go;
    input.onkeydown = e => { if (e.key === 'Enter') go(); };
  }

  function renderAccount(box) {
    const st = G.DB.guest ? 'guest' : G.DB.syncState;
    const SYNC = { ok: 'Guardado en la nube', syncing: 'Guardando…', pending: 'Pendiente de subir (se sube al salir del juego)',
                   offline: 'Sin conexión: se subirá al volver', local: 'Guardado sólo en este navegador', guest: 'Invitado: no se guarda' };
    if (G.DB.guest) {
      box.innerHTML = section('Cuenta', 'Estás jugando como <b>invitado</b>: tu progreso no se guarda al salir.')
        + `<button class="btn gold" id="set-login">Crear cuenta o entrar</button>`;
      return;
    }
    const nick = G.Social.me ? G.Social.me.name : (G.DB.user || '');
    const kind = G.DB.mode === 'local' ? 'Cuenta de este navegador' : G.DB.nameAccount ? 'Nombre y contraseña' : 'Google';
    box.innerHTML = section('Cuenta')
      + `<div class="set-row"><div class="grow"><b>Apodo</b><small>Es único y no se puede cambiar.</small></div><span class="gold" translate="no">${esc(nick)}</span></div>`
      + `<div class="set-row"><div class="grow"><b>Tipo de cuenta</b></div><span>${esc(kind)}</span></div>`
      + `<div class="set-row"><div class="grow"><b>Partida</b></div><span>${esc(SYNC[st] || st)}</span></div>`
      + `<div class="row wrap" style="gap:8px;margin-top:12px">
           <button class="btn" id="set-logout">Cerrar sesión</button>
           <button class="btn danger" id="set-delete">Borrar cuenta</button>
         </div><p class="note" id="set-msg"></p>`;
  }

  function wire(box) {
    box.querySelectorAll('.switch[data-k]').forEach(b => { b.onclick = () => { G.Settings.set(b.dataset.k, !G.Settings.get(b.dataset.k)); render(); }; });
    box.querySelectorAll('.chip[data-k]').forEach(b => {
      b.onclick = () => { const v = b.dataset.v; G.Settings.set(b.dataset.k, isNaN(+v) ? v : +v); render(); };
    });
    const full = $('set-full'); if (full) full.onclick = toggleFull;
    const lay = $('set-layout'); if (lay) lay.onclick = () => G.LayoutUI.open();
    box.querySelectorAll('[data-lang]').forEach(b => { b.onclick = () => { if (b.dataset.lang !== G.I18n.lang) G.I18n.set(b.dataset.lang); }; });
    const lo = $('set-login'); if (lo) lo.onclick = () => { close(); leave(); };
    const out = $('set-logout'); if (out) out.onclick = () => { close(); leave(); };
    const del = $('set-delete');
    if (del) del.onclick = async () => {
      const ok = await G.UI.confirmDelete();
      if (!ok) return;
      del.disabled = true;
      const r = await G.DB.deleteAccount(ok.pass);
      if (!r.ok) { $('set-msg').textContent = r.error; del.disabled = false; return; }
      close();
      G.UI.toast('Cuenta borrada');
      G.Audio.music(null);
      G.Flow.toLogin();
    };
  }

  /** Cerrar sesión (si estás en una partida, se abandona). */
  function leave() {
    if (G.DB.guest && !confirm('Eres invitado: se perderá todo el progreso. ¿Salir?')) return;
    if (G.Game.state !== 'ui') G.Game.quit && G.Game.quit();
    G.Audio.music(null);
    G.DB.logout().then(() => G.Flow.toLogin());
  }

  return { init, open, close, get isOpen() { return isOpen(); } };
})();

;
/* js/ui/layout-ui.js */
/* ============ layout-ui.js — colocar los botones (móvil) ============
 * Ajustes > Controles > Colocar los botones: se ven los ataques (con el
 * objeto), la pausa y, si es fijo, el joystick, y se arrastran a donde se
 * quiera. Se guarda el centro de cada cosa en proporción a la pantalla
 * (G.Settings 'pad'); lo que no se mueve se queda en su sitio de siempre.
 * El HUD (hud.js) y el joystick (touch.js) leen esas posiciones.
 * Las medidas copian las del HUD: si cambian allí, cambiarlas aquí.
 */
G.LayoutUI = (() => {
  const S = 54, GAP = 9, ITEM_GAP = 18, N = 4;          // como en hud.js
  const BAR_W = S + ITEM_GAP + N * S + (N - 1) * GAP;
  let el = null, pos = null, moved = null, mode = 'float';

  /** Dónde está cada cosa ahora mismo (centro en px), con lo guardado o lo de siempre. */
  function current(k, w, h) {
    const p = G.Touch.spot(k);
    if (k === 'stick') { const b = G.Touch.stickBase(w, h); return [b.x, b.y]; }
    const sa = G.Touch.safeArea();
    if (k === 'bar') {
      if (p) return [p[0] * w, p[1] * h];
      const totalW = N * S + (N - 1) * GAP;
      const left = (w - totalW) / 2 - S - ITEM_GAP;
      return [left + BAR_W / 2, h - S - 18 - Math.min(28, sa.bottom) + S / 2];
    }
    if (p) return [p[0] * w, p[1] * h];
    return [w - 52 - Math.min(44, sa.right) + 20, 12 + Math.min(20, sa.top) + 20];
  }

  /** Lo mismo que hace el HUD para que no se salga de la pantalla. */
  function fit(k, x, y, w, h) {
    if (k === 'bar') return [G.U.clamp(x, 6 + BAR_W / 2, Math.max(6 + BAR_W / 2, w - BAR_W / 2 - 6)), G.U.clamp(y, 24 + S / 2, h - S / 2 - 6)];
    if (k === 'pause') return [G.U.clamp(x, 24, w - 24), G.U.clamp(y, 30, h - 24)];
    const r = G.Touch.R();
    return [G.U.clamp(x, r + 4, w - r - 4), G.U.clamp(y, r + 4, h - r - 4)];
  }

  function build() {
    el = document.createElement('section');
    el.id = 'scr-layout';
    el.className = 'scr hidden';
    const slots = Array.from({ length: N }, (_, i) => `<div class="lay-slot${i === 0 ? ' on' : ''}"><i>${i + 1}</i></div>`).join('');
    el.innerHTML = `
      <div class="lay-thing lay-bar" data-k="bar"><div class="lay-slot item"></div>${slots}<span class="lay-tag">Ataques</span></div>
      <div class="lay-thing lay-pause" data-k="pause"><b></b><b></b></div>
      <div class="lay-thing lay-stick" data-k="stick"><div class="knob"></div><span class="lay-tag">Joystick</span></div>
      <div class="box lay-panel">
        <h3>Arrastra los botones a donde quieras</h3>
        <p class="lay-turn">Gira el móvil: se juega en horizontal.</p>
        <div class="chips set-chips" id="lay-mode"><b>Joystick</b>
          <button class="chip" data-m="float">Flotante</button><button class="chip" data-m="fixed">Fijo</button>
        </div>
        <small class="lay-help">Flotante: aparece donde pones el dedo. Fijo: siempre en el mismo sitio.</small>
        <div class="row wrap lay-btns">
          <button class="btn small ghost" id="lay-cancel">Cancelar</button>
          <button class="btn small" id="lay-reset">Restablecer</button>
          <button class="btn small gold" id="lay-save">Guardar</button>
        </div>
      </div>`;
    document.body.appendChild(el);
    el.querySelectorAll('.lay-thing').forEach(drag);
    el.querySelectorAll('#lay-mode .chip').forEach(b => { b.onclick = () => { mode = b.dataset.m; paint(); }; });
    el.querySelector('#lay-cancel').onclick = close;
    el.querySelector('#lay-reset').onclick = () => {
      moved = {}; mode = 'float';
      const w = innerWidth, h = innerHeight, sa = G.Touch.safeArea();
      const totalW = N * S + (N - 1) * GAP;
      pos = { bar: [(w - totalW) / 2 - S - ITEM_GAP + BAR_W / 2, h - S - 18 - Math.min(28, sa.bottom) + S / 2],
              pause: [w - 52 - Math.min(44, sa.right) + 20, 12 + Math.min(20, sa.top) + 20],
              stick: [G.Touch.STICK_DEF[0] * w, G.Touch.STICK_DEF[1] * h] };
      for (const k in pos) pos[k] = fit(k, pos[k][0], pos[k][1], w, h);
      paint();
    };
    el.querySelector('#lay-save').onclick = save;
    addEventListener('resize', () => { if (isOpen()) { load(); paint(); } });
  }

  function drag(node) {
    const k = node.dataset.k;
    let off = null;
    node.addEventListener('pointerdown', e => {
      e.preventDefault();
      off = [e.clientX - pos[k][0], e.clientY - pos[k][1]];
      node.classList.add('held');
      try { node.setPointerCapture(e.pointerId); } catch (err) { /* nada */ }
    });
    node.addEventListener('pointermove', e => {
      if (!off) return;
      pos[k] = fit(k, e.clientX - off[0], e.clientY - off[1], innerWidth, innerHeight);
      moved[k] = true;
      paint();
    });
    const up = () => { off = null; node.classList.remove('held'); };
    node.addEventListener('pointerup', up);
    node.addEventListener('pointercancel', up);
  }

  function load() {
    const w = innerWidth, h = innerHeight;
    pos = {}; moved = {};
    for (const k of ['bar', 'pause', 'stick']) {
      const c = current(k, w, h);
      pos[k] = fit(k, c[0], c[1], w, h);
      moved[k] = !!G.Touch.spot(k);
    }
  }

  function paint() {
    const r = G.Touch.R();
    const place = (k, ww, hh) => {
      const n = el.querySelector(`[data-k="${k}"]`);
      n.style.left = (pos[k][0] - ww / 2) + 'px'; n.style.top = (pos[k][1] - hh / 2) + 'px';
      n.style.width = ww + 'px'; n.style.height = hh + 'px';
      return n;
    };
    place('bar', BAR_W, S);
    place('pause', 40, 40);
    place('stick', r * 2, r * 2).classList.toggle('hidden', mode !== 'fixed');
    el.querySelectorAll('#lay-mode .chip').forEach(b => b.classList.toggle('on', b.dataset.m === mode));
    el.querySelector('.lay-turn').classList.toggle('hidden', innerWidth >= innerHeight);
  }

  function save() {
    const w = innerWidth, h = innerHeight, pad = {};
    for (const k in pos) if (moved[k]) pad[k] = [+(pos[k][0] / w).toFixed(4), +(pos[k][1] / h).toFixed(4)];
    G.Settings.set('pad', Object.keys(pad).length ? pad : null);
    G.Settings.set('stickMode', mode);
    G.UI.toast('Botones colocados');
    close();
  }

  function open() {
    if (!el) build();
    mode = G.Settings.get('stickMode') === 'fixed' ? 'fixed' : 'float';
    load();
    el.classList.remove('hidden');
    paint();
  }
  function close() { if (el) el.classList.add('hidden'); }
  const isOpen = () => !!el && !el.classList.contains('hidden');

  return { open, close, get isOpen() { return isOpen(); } };
})();

;
/* js/ui/support-ui.js */
/* ============ support-ui.js — "Apoyar el proyecto" ============
 * Botón con un corazón en la barra del menú (sólo si hay cuenta de Ko-fi en
 * js/data/funding.js) y una ventana que explica, con números, a qué va el
 * dinero. No se cobra nada dentro del juego: el pago es en Ko-fi.
 */
G.SupportUI = (() => {
  const $ = G.UI.$;
  const F = G.Funding;
  const val = v => typeof v === 'number'
    ? (Math.round(v * 100) / 100).toLocaleString(G.I18n.lang === 'en' ? 'en' : 'es', { style: 'currency', currency: 'EUR' }) + ' / mes'
    : v;

  function init() {
    const b = $('btn-support');
    b.classList.remove('hidden');
    b.innerHTML = G.Icons.html('heart', 18) + ' <span>Apoyar</span>';
    b.onclick = open;
    $('sup-close').onclick = close;
  }

  // Sin enlaces ni donaciones: el botón es una broma.
  function open() {
    $('sup-body').innerHTML = `
      <p style="text-align:center;font-size:22px;margin:18px 0 8px">Buy Ryan a Taco Bell</p>
      <p class="sub" style="text-align:center;margin-bottom:6px">(this is a joke, the game is free and always will be)</p>`;
    $('scr-support').classList.remove('hidden');
  }
  function close() { $('scr-support').classList.add('hidden'); }

  return { init, open, close };
})();

